    ["Yrth"] = {
        ["Thanks for all your help!"] = "¡Gracias por toda tu ayuda!",
        ["Thank you for helping me reach your realm adventurer. We have work to do!"] = "Gracias por ayudarme a llegar a tu reino aventurero. ¡Tenemos trabajo que hacer!",
    },
    ["Ysgawyn"] = {
        ["Hey ya."] = "Hola, sí.",
        ["Can I help you?"] = "¿Puedo ayudarte?",
        ["Not really I just wanted to chat."] = "En realidad no, sólo quería charlar.",
        ["Sorry, I do not have time for idle gossip. Good day."] = "Lo siento, no tengo tiempo para chismes. Buen día.",
    },
    ["Ysondria"] = {
        ["Greetings, stranger. Have you been sent to help us in the fight to purify this area from the invading corruption?"] = "Saludos, extraño. ¿Ha sido enviado para ayudarnos en la lucha para purificar esta zona de la corrupción invasora?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes."] = "Sí.",
        ["I am so glad. We need everyone we can get."] = "Me alegro mucho. Necesitamos a todos los que podamos conseguir.",
        ["I can only hope that you still want to help when I have given you more details."] = "Sólo puedo esperar que todavía quieras ayudar cuando te haya dado más detalles.",
        ["That is a shame. There is grave danger here."] = "Eso es una pena. Aquí hay un grave peligro.",
        ["Maybe if you hear my tale you will be willing to help?"] = "¿Tal vez si escuchas mi historia estarás dispuesto a ayudar?",
        ["Would you like a charmed sack so you can collect corruption?"] = "¿Te gustaría un saco encantado para poder recolectar corrupción?",
        ["You do not have enough space to carry the sack at the moment."] = "No tienes suficiente espacio para llevar el saco en este momento.",
        ["There you go."] = "Ahí lo tienes.",
        ["Is there any other help that I can give you?"] = "¿Hay alguna otra ayuda que pueda brindarte?",
        ["Hello again, Player."] = "Hola de nuevo, Player.",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["Faith is the answer."] = "La fe es la respuesta.",
        ["The creature is a being of malice and evil; a scar on our land. In this way, it holds the seeds of its own destruction."] = "La criatura es un ser de malicia y maldad; una cicatriz en nuestra tierra. De esta manera, contiene las semillas de su propia destrucción.",
        ["The reason it polluted the area is that it cannot survive in pure conditions."] = "La razón por la que contaminó el área es que no puede sobrevivir en condiciones puras.",
        ["So we purify the land?"] = "¿Entonces purificamos la tierra?",
        ["Even better. With our faith and strength of spirit channelled into the pillars, we can purify the corruption that it is spewing forth and feed it back to itself, purifying it from the inside out."] = "Aún mejor. Con nuestra fe y fuerza de espíritu canalizadas en los pilares, podemos purificar la corrupción que está arrojando y retroalimentarla a sí misma, purificándola de adentro hacia afuera.",
        ["In this way we will destroy the beast and remove its foul grip on the land."] = "De esta manera destruiremos the beast y eliminaremos su asqueroso control sobre la tierra.",
        ["How does it work?"] = "¿Cómo funciona?",
        ["The Nexus where that thing is trying to break through is the key. Its corruption, the power it uses to taint the land, escapes."] = "El Nexo por donde esa cosa intenta abrirse paso es la clave. Su corrupción, el poder que utiliza para contaminar la tierra, escapa.",
        ["If we collect this corruption, the foul orange cloud, we can feed it back to it through the pillars."] = "Si recolectamos esta corrupción, la repugnante nube naranja, podemos devolverla a través de los pilares.",
        ["In order to use the pillars you need to use the power of prayer."] = "Para usar los pilares necesitas usar el poder de la oración.",
        ["How does prayer help?"] = "¿Cómo ayuda la oración?",
        ["How do I collect the corruption?"] = "¿Cómo recojo la corrupción?",
        ["Is there a way to speed up the process?"] = "¿Hay alguna manera de acelerar el proceso?",
        ["Let's get down to business."] = "Pongámonos manos a la obra.",
        ["How does faith help?"] = "¿Cómo ayuda la fe?",
        ["This is simpler than it sounds."] = "Esto es más simple de lo que parece.",
        ["Each bowl on the pillars is attuned to a different aspect of the spirit: order, chaos, battle and fealty - for which everyone has the potential."] = "Cada cuenco sobre los pilares está en sintonía con un aspecto diferente del espíritu: orden, caos, batalla y lealtad, para lo cual todos tienen el potencial.",
        ["All you have to do is muster your strength of will, holding the necessary aspect firmly in your heart as you pour the corruption into the bowl, and the pillars will do the rest."] = "Todo lo que tienes que hacer es reunir tu fuerza de voluntad, manteniendo firmemente el aspecto necesario en tu corazón mientras viertes la corrupción en el cuenco, y los pilares harán el resto.",
        ["Your spiritual strength will increase as you do this."] = "Tu fuerza espiritual aumentará a medida que hagas esto.",
        ["The charmed sack that you have has been woven to allow it to hold the corruption."] = "El saco encantado que tienes ha sido tejido para permitirle contener la corrupción.",
        ["Go to the Nexus to collect the corruption."] = "Ve al Nexus para recoger la corrupción.",
        ["We have found that the effect of the purification is much stronger if each of the pillars is channelling a different aspect."] = "Hemos descubierto que el efecto de la purificación es mucho más fuerte si cada uno de los pilares canaliza un aspecto diferente.",
        ["This seems to amplify the purity that we are sending into the Nexus, and I can feel the evil there recoiling."] = "Esto parece amplificar la pureza que estamos enviando al Nexo, y puedo sentir el mal retroceder allí.",
        ["There is, however, a side effect to this."] = "Sin embargo, esto tiene un efecto secundario.",
        ["What are the side effects?"] = "¿Cuáles son los efectos secundarios?",
        ["When it gets angered it uses this energy to try to break through the Nexus."] = "Cuando se enoja, utiliza esta energía para intentar atravesar el Nexo.",
        ["It rarely gets far - usually just interrupting the flow for a few moments - but sometimes..."] = "Rara vez llega lejos, generalmente solo interrumpe el flujo por unos momentos, pero a veces...",
        ["Go on..."] = "Continúa...",
        ["It...emerges, showing its unspeakable face. You must be ready to banish it with every ounce of your will if this happens."] = "Él... emerge, mostrando su rostro indescriptible. Debes estar preparado para desterrarlo con cada gramo de tu voluntad si esto sucede.",
        ["It cannot be allowed to break free!"] = "¡No se puede permitir que se libere!",
        ["What is happening here?"] = "¿Qué está pasando aquí?",
        ["Our beautiful land has been contaminated by that horror. It must be stopped."] = "Nuestra hermosa tierra ha sido contaminada por ese horror. Hay que detenerlo.",
        ["What is that thing?"] = "¿Qué es esa cosa?",
        ["It is a creature of nightmares. I do not know its name, and do not wish to. It is an abomination and must be stopped."] = "Es una criatura de pesadillas. No sé su nombre y no deseo saberlo. Es una abominación y hay que detenerlo.",
        ["What kind of creature is it?"] = "¿Qué clase de criatura es?",
        ["Again, I do not know. many years, warping the land into the dank morass you see here. That is why I call it the Grotesque."] = "Nuevamente, no lo sé. muchos años, transformando la tierra en el pantano húmedo que ves aquí. Por eso lo llamo Grotesco.",
        ["If it has been here for many years, why was there no evidence of it?"] = "Si ha estado aquí durante muchos años, ¿por qué no había pruebas de ello?",
        ["Oh, there was. Have you ever been to the tunnels beneath these swamps and seen the hands reaching from the walls? They were the first evidence of this horror."] = "Oh, lo hubo. ¿Alguna vez has estado en los túneles debajo de estos pantanos y has visto las manos saliendo de las paredes? Fueron la primera evidencia de este horror.",
        ["Why didn't you do something back then?"] = "¿Por qué no hiciste algo en aquel entonces?",
        ["Ah, if we had known then what we do now, perhaps we could have salvaged some of this area; stopped the growth of the monstrosity."] = "Ah, si hubiéramos sabido entonces lo que hacemos ahora, tal vez podríamos haber salvado parte de esta área; Detuvo el crecimiento de la monstruosidad.",
        ["My mentor - Augrum - came to study the area when he heard about the hands. For all his wisdom, he had no way of knowing the extent of the evil here."] = "Mi mentor, Augrum, vino a estudiar el área cuando se enteró de las manos. A pesar de toda su sabiduría, no tenía forma de saber el alcance del mal aquí.",
        ["What did he do?"] = "¿Qué hizo?",
        ["For some time he studied the hands and the surrounding area, but without knowing how insidious the creature was. He thought it was safe - that it wasn't growing...that it wouldn't hurt us."] = "Durante algún tiempo estudió las manos y el área circundante, pero sin saber cuán insidiosa era la criatura. Pensó que era seguro, que no estaba creciendo... que no nos haría daño.",
        ["So he sent me - his apprentice - to watch over the area."] = "Así que me envió a mí, su aprendiz, a vigilar la zona.",
        ["By the time I realised the extent of the danger, it was too late."] = "Cuando me di cuenta de la magnitud del peligro, ya era demasiado tarde.",
        ["When it became clear it was growing in power, I called Augrum to investigate."] = "Cuando quedó claro que su poder estaba creciendo, llamé a Augrum para investigar.",
        ["It was clear to Augrum that the corruption in the area had grown and that - left unchecked - it could destroy the area."] = "Augrum tenía claro que la corrupción en la zona había aumentado y que, si no se controlaba, podría destruir la zona.",
        ["So he went away, to seek help fighting the beast."] = "Entonces se fue a buscar ayuda para luchar contra the beast.",
        ["Where did he go?"] = "¿A dónde fue?",
        ["He went to visit some druids he'd heard of, far from here. He never said where exactly - only that they had some...radical ideas."] = "Fue a visitar a unos druidas de los que había oído hablar, lejos de aquí. Nunca dijo dónde exactamente, sólo que tenían algunas... ideas radicales.",
        ["Those were the hardest times, being here with that evil growing, not knowing when - or if - Augrum was going to come back."] = "Esos fueron los momentos más difíciles, estar aquí con ese mal creciendo, sin saber cuándo, o si, Augrum iba a regresar.",
        ["But he did?"] = "¿Pero lo hizo?",
        ["Yes. After many months he came back. This was only a few days ago. He came with some of the druids he'd spoken of - wild-eyed, feral men in tattered robes - carrying the four pillars you see here between them."] = "Sí. Después de muchos meses regresó. Esto fue hace sólo unos días. Vino con algunos de los druidas de los que había hablado (hombres salvajes con ojos desorbitados y túnicas hechas jirones) llevando los cuatro pilares que ves aquí entre ellos.",
        ["Augrum was very ill when he got back - he was an old man, and the journey had taken its toll. Also, the price he paid for the druids' assistance was...high."] = "Augrum estaba muy enfermo cuando regresó; era un old man y el viaje le había pasado factura. Además, el precio que pagó por la ayuda de los druidas fue... alto.",
        ["What cost?"] = "¿Cuánto cuesta?",
        ["I cannot bring myself to speak of that now. Suffice it to say that he died in the cause of protecting the land. Perhaps later we will speak further on this."] = "No puedo atreverme a hablar de eso ahora. Baste decir que murió por la causa de proteger la tierra. Quizás más adelante hablemos más sobre esto.",
        ["What did the druids do?"] = "¿Qué hicieron los druidas?",
        ["The druids did not speak, not even to Augrum. They just set up the pillar in the formation you see, and dug the channels. When they had finished, they simply left."] = "Los druidas no hablaron, ni siquiera con Augrum. Simplemente colocaron el pilar en la formación que ves y cavaron los canales. Cuando terminaron, simplemente se fueron.",
        ["I spent most of that time with Augrum, as he explained to me how the pillars can be used to force back the evil."] = "Pasé la mayor parte de ese tiempo con Augrum, mientras él me explicaba cómo se pueden usar los pilares para hacer retroceder al mal.",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Ysondria: Guardian of the Nexus. It is my responsibility to make sure that the monstrosity trying to break through doesn't get out to spread its evil elsewhere."] = "Soy Ysondria: Guardián del Nexo. Es mi responsabilidad asegurarme de que la monstruosidad que intenta abrirse paso no salga y propague su maldad en otros lugares.",
        ["What is the Nexus?"] = "¿Qué es el Nexus?",
        ["It is the point at which the creature is trying to break through the surface, but also where it is at its weakest; its most exposed."] = "Es el punto en el que la criatura intenta atravesar la superficie, pero también donde está más débil; está más expuesto.",
        ["Not right now."] = "No ahora mismo.",
        ["I wish you luck and hope that you will work hard to aid this."] = "Te deseo suerte y espero que trabajes duro para ayudar en esto.",
        ["You already have a charmed sack. Collect corruption from the Nexus and purify it at one of the pillars."] = "Ya tienes un saco encantado. Recoge la corrupción del Nexus y purifícala en uno de los pilares.",
        ["Thank you again, Player. I was worried this day would not come, but you have stopped the corruption."] = "Gracias de nuevo, Player. Me preocupaba que este día no llegara, pero ustedes han detenido la corrupción.",
        ["There is some residual energy in the sack. Allow me to release it back to you."] = "Hay algo de energía residual en el saco. Permítame devolvérselo.",
        ["I shall be forever grateful for your aid in releasing this land."] = "Estaré eternamente agradecido por su ayuda para liberar esta tierra.",
        ["The effects of the purification can already be seen. I believe that the memory of Augrum is honoured by the work completed here."] = "Los efectos de la purificación ya se pueden ver. Creo que the memory de Augrum se siente honrado por el trabajo realizado aquí.",
        ["Select an Option {{anchor"] = "Seleccione una opción {{anchor",
        ["How can I train my spiritual skills now?"] = "¿Cómo puedo entrenar mis habilidades espirituales ahora?",
        ["Traditionally, ceremonial burial is used to honour the dead. To do this, you need to bury the bones of those that have been killed."] = "Tradicionalmente, el entierro ceremonial se utiliza para honrar a los muertos. Para hacer esto, debes enterrar los huesos de los que han sido asesinados.",
        ["As I understand it, the more powerful that the creature was when it was alive, the greater the experience you receive from burying the bones."] = "Según tengo entendido, cuanto más poderosa era la criatura cuando estaba viva, mayor es la experiencia que recibes al enterrar los huesos.",
        ["If you are devoted to training your spiritual abilities, you can create a gilded altar in your home to boost this process."] = "Si te dedicas a entrenar tus habilidades espirituales, puedes crear un altar dorado en tu casa para impulsar este proceso.",
        ["I have also heard of something called the Ectofuntus, which grants increased experience from bones, but I do not know what this is. All I do know is that it is located near to Port Phasmatys, far to the north-east."] = "También he oído hablar de algo llamado Ectofuntus, que otorga mayor experiencia a partir de huesos, pero no sé qué es. Lo único que sé es que está situado cerca de Port Phasmatys, muy al noreste.",
        ["Who is Augrum?"] = "¿Quién es Augrum?",
        ["Augrum was my mentor. He gave his life creating those relics as a means to release the land from its inevitable decay."] = "Augrum fue mi mentor. Dio su vida creando esas reliquias como un medio para liberar a la tierra de su inevitable decadencia.",
        ["He was a very brave and kind-hearted man, and I am grateful for your help in realising his intent."] = "Era un hombre muy valiente y de buen corazón, y agradezco su ayuda para hacer realidad su intención.",
        ["Will the area stay cleansed?"] = "¿El área permanecerá limpia?",
        ["I believe that it will, through the hard work that you have done here. I will not allow that evil to come back."] = "Creo que así será, gracias al arduo trabajo que has realizado aquí. No permitiré que ese mal vuelva.",
        ["Why are you still here?"] = "¿Por qué sigues aquí?",
        ["I feel close to Augrum here, and I want to ensure that everyone knows what he did, and what he sacrificed in order to free this land from that corruption."] = "Me siento cercano a Augrum aquí y quiero asegurarme de que todos sepan lo que hizo y lo que sacrificó para liberar esta tierra de esa corrupción.",
        ["I also wish to spread the word about all of the people who joined the fight and stood against the horror, using their faith and inner strength to save the land."] = "También deseo hacer correr la voz sobre todas las personas que se unieron a la lucha y se enfrentaron al horror, usando su fe y fuerza interior para salvar la tierra.",
        ["Goodbye."] = "Adiós.",
        ["Your aid will always be remembered."] = "Tu ayuda siempre será recordada.",
        ["The effects of the purification can already be seen. believe that the memory of Augrum is honoured by the work completed here."] = "Los efectos de la purificación ya se pueden ver. Creo que the memory de Augrum se siente honrado por el trabajo realizado aquí.",
        ["I shall be forever grateful for your aid in releasing this land. Your work is done here."] = "Estaré eternamente agradecido por su ayuda para liberar esta tierra. Tu trabajo está hecho aquí.",
        ["I knew you'd come. Here, take this."] = "Sabía que vendrías. Toma, toma esto.",
        ["[Ysondria has given you a challenge scroll!]"] = "[¡Ysondria te ha dado un pergamino de desafío!]",
        ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
        ["That's not right at all."] = "Eso no está nada bien.",
        ["[Ysondria has given you another clue scroll!]"] = "[¡Ysondria te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Correct!"] = "¡Correcto!",
    },
    ["Yuehanxun the Dealer"] = {
        ["Looking for something? Or someone?"] = "¿Buscas algo? ¿O alguien?",
        ["Yeah, I'm trying to track down a man called Jed. He's also known as the Iron Link."] = "Sí, estoy intentando localizar a un hombre llamado Jed. También se le conoce como Enlace de Hierro.",
        ["Can't say I've heard of such a person, and I make it my business to know everyone."] = "No puedo decir que haya oído hablar de una persona así, y me propongo conocer a todos.",
        ["Well, I guess it was a long shot. I figured he'd be quite notorious in the Arc."] = "Bueno, supongo que era una posibilidad remota. Pensé que sería bastante famoso en el Arco.",
    },
    ["Yulf Squecks"] = {
        ["You don't have a sapling planted in that patch. Plant one and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Plante uno y tal vez acepte cuidarlo por usted.",
        ["Alright, but it's not going to be cheap! I want [3/5] monkey nuts, a monkey bar and a ground-up Suqah tooth."] = "Muy bien, ¡pero no será barato! Quiero nueces de mono [3/5], una barra y un diente de Suqah molido.",
        ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
        ["Yes."] = "Sí.",
        ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
        ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
        ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
        ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
        ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
        ["Choose an option:"] = "Elige una opción:",
        ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
        ["You don't have a sapling planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Planta algo y tal vez acepte cuidarlo por ti.",
        ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
        ["First, I want [3/5] monkey nuts, a monkey bar and a ground up suqah tooth."] = "Primero, quiero nueces de mono [3/5], una barra de mono y un diente de suqah molido.",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["Where can I get all that stuff?"] = "¿Dónde puedo conseguir todo eso?",
        ["You can get a Suqah tooth from a Suqah's mouth, of course. Then you grind it up with a pestle and mortar. As for the monkey bar and nuts, try looking somewhere where there are lots of monkeys!"] = "Puedes obtener un diente de Suqah de la boca de una Suqah, por supuesto. Luego lo mueles con un mortero. En cuanto a la barra de monos y las nueces, ¡intenta buscar en algún lugar donde haya muchos monos!",
        ["Alright, I'll pay."] = "Muy bien, pagaré.",
        ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
        ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
        ["What the heck do you want with THAT?"] = "¿Qué diablos quieres con ESO?",
        ["They're for eating, silly! What else<br>can you do with a monkey bar?"] = "¡Son para comer, tonto! ¿Qué más<br>puedes hacer con una barra de mono?",
        ["And the Suqah tooth?"] = "¿Y el diente de Suqah?",
        ["Lots of gnomes like a bit of ground-up Suqah tooth, just don't tell anyone about this, okay?"] = "A muchos gnomos les gusta un poco de diente de Suqah molido, pero no le cuentes a nadie sobre esto, ¿de acuerdo?",
        ["Forget I asked."] = "Olvida que pregunté.",
        ["Maybe some other time."] = "Quizás en otro momento.",
        ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
        ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
        ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
        ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
        ["Can you sell me something?"] = "¿Puedes venderme algo?",
        ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["Select an Option"] = "Selecciona una opción",
        ["Some plant cure."] = "Alguna cura vegetal.",
        ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
        ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
        ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
        ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
        ["A bucket of compost."] = "Un balde de abono.",
        ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
        ["A rake."] = "Un rastrillo.",
        ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["(See more items)"] = "(Ver más artículos)",
        ["A watering can"] = "una regadera",
        ["A watering can."] = "Una regadera.",
        ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
        ["A gardening trowel"] = "Una paleta de jardinería",
        ["A gardening trowel."] = "Una paleta de jardinería.",
        ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["A seed dibber"] = "Un zambullidor de semillas",
        ["A seed dibber."] = "Un arrancador de semillas.",
        ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["(See previous items)"] = "(Ver artículos anteriores)",
        ["Forget it."] = "Olvídalo.",
        ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
        ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
        ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    },
    ["Yuri"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
}

dialogues.all = {
    ["You look strong. Welcome to the Strength testing area of the Warriors' Guild. I am Yadech. I am looking after this area now that Sloane has gone to the Hall of Warriors to drink for eternity."] = "Te ves fuerte. Bienvenido al área de pruebas Strength del Warriors' Guild. Soy Yadech. Estoy cuidando esta área ahora que Sloane ha ido al Salón de los Guerreros a beber por la eternidad.",
    ["Ahhh, hello there, Player."] = "Ahhh, hola, Player.",
    ["Ah, but I can see you are already as strong as is possible! Perhaps you have come to me to purchase a Skillcape of Strength, and thus join the elite few who have mastered this exacting skill?"] = "¡Ah, pero puedo ver que ya eres lo más fuerte posible! ¿Quizás has venido a mí para comprar un Skillcape o un Strength y así unirte a la élite que domina esta exigente habilidad?",
    ["Select an Option"] = "Selecciona una opción",
    ["Can you tell me a bit about skillcapes?"] = "¿Puedes contarme un poco sobre skillcapes?",
    ["Sure. You can buy a skillcape when you reach level 99 in a skill. Apart from boosting your statistics in that skill, they can also be used to perform some pretty amazing emotes! Is there anything else you would like to know?"] = "Claro. Puedes comprar un skillcape cuando alcances el nivel 99 en una habilidad. Además de mejorar tus estadísticas en esa habilidad, ¡también pueden usarse para realizar algunos gestos increíbles! ¿Hay algo más que te gustaría saber?",
    ["May I buy a Skillcape of Strength, please?"] = "¿Puedo comprar un Skillcape de Strength, por favor?",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["Choose an option:"] = "Elige una opción:",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["Hmm, yes, you certainly look strong enough. That'll be 99,000 gold coins, please."] = "Hmm, sí, ciertamente te ves lo suficientemente fuerte. Serán 99.000 gold coins, por favor.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
    ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
    ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
    ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Strength master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Strength master cape.",
    ["Buy Strength master cape for 120,000 coins?"] = "¿Comprar Strength master cape por 120.000 coins?",
    ["Yes."] = "Sí.",
    ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
    ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Strength skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Strength skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Strength skillcape."] = "Solo me gustaría cambiar el Strength skillcape.",
    ["No problem, you will now use the [older/newer] model for your Strength skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Strength skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["No, thank you."] = "No, gracias.",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["No, thanks."] = "No, gracias.",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["Ahh, the shot put is a great test of strength and can be quite rewarding. Mind you do it properly, though, you might want to dust your hands with some powdery substance first. It'll give better grip."] = "Ahh, el lanzamiento de peso es una gran prueba de fuerza y ​​puede ser bastante gratificante. Eso sí, asegúrate de hacerlo correctamente; es posible que primero quieras espolvorearte las manos con alguna sustancia en polvo. Le dará un mejor agarre.",
    ["I'll remember that. What should I use?"] = "Lo recordaré. ¿Qué debo usar?",
    ["I personally prefer ground ashes, it makes a nice fine powder and gives some really good grip."] = "Personalmente prefiero las cenizas molidas, produce un polvo fino y agradable y proporciona un agarre realmente bueno.",
    ["Okay, what else?"] = "Vale, ¿qué más?",
    ["Basically you'll need to go in there, make sure you've got nothing cluttering up your hands, pick up a shot and throw it. Depending upon your technique, you can get quite long throws."] = "Básicamente tendrás que entrar allí, asegurarte de no tener nada en tus manos, tomar un tiro y lanzarlo. Dependiendo de tu técnica, puedes realizar lanzamientos bastante largos.",
    ["What was your best?"] = "¿Cuál fue tu mejor?",
    ["Ahh, that would be telling."] = "Ahh, eso sería revelador.",
    ["Why are you wielding a tree branch?"] = "¿Por qué empuñas la rama de un árbol?",
    ["Well...there's a story to that. You see, I should have an axe but-"] = "Bueno... hay una historia en eso. Verás, debería tener un hacha, pero...",
    ["Sloane's axe?"] = "¿El hacha de Sloane?",
    ["My axe. He won it because of a squirrel."] = "Mi hacha. Lo ganó gracias a una ardilla.",
    ["A squirrel?"] = "¿Una ardilla?",
    ["He bet me that I couldn't catch the squirrel while still holding my axe, but that he could...but he tricked me!"] = "Me apostó a que no podría atrapar a la ardilla mientras todavía sostenía mi hacha, pero que él sí... ¡pero me engañó!",
    ["Ahh, yes, Sloane told me that story before...how you tried to chase the squirrel up the tree with your axe, but that he just chopped the tree down with your axe and won it."] = "Ahh, sí, Sloane me contó esa historia antes... cómo intentaste perseguir a la ardilla hasta el árbol con tu hacha, pero él simplemente cortó el árbol con tu hacha y ganó.",
    ["Yes, this is so."] = "Sí, así es.",
    ["It doesn't explain why you have a tree branch, though."] = "Sin embargo, eso no explica por qué tienes una rama de árbol.",
    ["A barbarian warrior is bound to his axe, I cannot take up another unless my axe is ruined beyond repair. So I used part of the tree that Sloane cut down as my weapon...it also reminds me of him."] = "Un guerrero bárbaro está atado a su hacha, no puedo tomar otra a menos que mi hacha esté arruinada sin posibilidad de reparación. Así que usé parte del árbol que Sloane cortó como arma... también me recuerda a él.",
    ["He was a great warrior."] = "Era un gran guerrero.",
    ["But he would want us to be happy that he is now with his warrior brethren. Can I help you with anything else?"] = "Pero él querría que estemos felices de estar ahora con sus hermanos guerreros. ¿Puedo ayudarte con algo más?",
    ["Bye!"] = "¡Adiós!",
    ["Be well, warrior Player."] = "Que estés bien, guerrero Player.",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["Out of my way, punk."] = "Fuera de mi camino, punk.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
    ["Strange how?"] = "¿Qué extraño cómo?",
    ["Like a human!"] = "¡Como un humano!",
    ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
    ["*Dialogue 5*"] = "*Diálogo 5*",
    ["Get lost!"] = "¡Piérdete!",
    ["*Dialogue 6*"] = "*Diálogo 6*",
    ["Leave me alone."] = "Déjame en paz.",
    ["*Dialogue 7*"] = "*Diálogo 7*",
    ["Have you no manners?"] = "¿No tienes modales?",
    ["*Dialogue 8*"] = "*Diálogo 8*",
    ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
    ["*Dialogue 9*"] = "*Diálogo 9*",
    ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
    ["*Dialogue 10*"] = "*Diálogo 10*",
    ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
    ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
    ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
    ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
    ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
    ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
    ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
    ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
    ["Good day to you, my friend."] = "Buenos días, amigo mío.",
    ["You smell familiar..."] = "Hueles familiar...",
    ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    ["[You find nothing of interest on the body.]"] = "[No encuentra nada de interés en el cuerpo.]",
    ["Yakamaru's waters begin to drench you!"] = "¡Las aguas de Yakamaru empiezan a empaparte!",
    ["Yakamaru's waters soak through you!"] = "¡Las aguas de Yakamaru te empapan!",
    ["Yakamaru's waters conduct his full power!"] = "¡Las aguas de Yakamaru conducen todo su poder!",
    ["Yakamaru is displeased by your cowardice and flings dangerous projectiles at you!"] = "¡Yakamaru está disgustado por tu cobardía y te lanza peligrosos proyectiles!",
    ["Yakamaru drops your team into quicksand! Free them before they drown!"] = "¡Yakamaru deja a tu equipo en arenas movedizas! ¡Libéralos antes de que se ahoguen!",
    ["You grab hold of [name] and quickly pull them out of the quicksand!"] = "¡Agarras a [name] y rápidamente los sacas de las arenas movedizas!",
    ["[name] grabs you and pulls you out of the quicksand!"] = "¡[name] te agarra y te saca de las arenas movedizas!",
    ["[name] has stunned Yakamaru!"] = "¡[name] ha sorprendido a Yakamaru!",
    ["Yakamaru releases the dangerous poison!"] = "¡Yakamaru libera el peligroso veneno!",
    ["Yakamaru releases the dangerous poison!}"] = "¡Yakamaru libera el peligroso veneno!}",
    ["You absorb the insane poison. There is no cure - stand next to Yakamaru as it dies to pass it over."] = "Absorbes el veneno loco. No hay cura: párate junto a Yakamaru mientras muere para pasarlo por alto.",
    ["No one poisoned Yakamaru so it heads to the central pool to recover."] = "Nadie envenenó a Yakamaru por lo que se dirige a la piscina central para recuperarse.",
    ["Yakamaru is lured by the scent of your poison!"] = "¡Yakamaru se siente atraído por el olor de tu veneno!",
    ["This player is already receiving aid."] = "Este jugador ya está recibiendo ayuda.",
    ["As the [Jellyfish] dies, it cleanses the poisonous effect on Yakamaru!"] = "¡A medida que [Jellyfish] muere, limpia el efecto venenoso de Yakamaru!",
    ["As the [Jellyfish] touches Yakamaru, it cleanses the poisonous effect!"] = "Cuando [Jellyfish] toca Yakamaru, ¡limpia el efecto venenoso!",
    ["An Image of Yakamaru is not engaged in combat and flings dangerous projectiles at the team!"] = "¡Una imagen de Yakamaru no está en combate y lanza peligrosos proyectiles al equipo!",
    ["You still need [number loads/one more load] of sand to finish blocking this pool."] = "Aún necesitas [number loads/one more load] de arena para terminar de bloquear esta piscina.",
    ["In desperation, Yakamaru sees the Durable Jellyfish, and consumes it, healing him fully!"] = "Desesperado, Yakamaru ve la medusa duradera y la consume, curándolo por completo.",
    ["Who are you?"] = "¿Quién eres?",
    ["The name's Yaktwee."] = "El nombre es Yaktwee.",
    ["Yaktwee Swinmari Cianta. Pleased to meet ya."] = "Yaktwee Swinmari Cianta. Encantado de conocerte.",
    ["Select an option"] = "Seleccione una opción",
    ["That's a strange name."] = "Ese es un nombre extraño.",
    ["Well, I like it, and my parents thought it suited me."] = "Bueno, me gusta y mis padres pensaron que me convenía.",
    ["Anyway, it's just something to call me by."] = "De todos modos, es algo para llamarme.",
    ["What are you doing here?"] = "¿Qué haces aquí?",
    ["Okay, thanks."] = "Bien, gracias.",
    ["Hey, Yaktwee. How are you?"] = "Hola, Yaktwee. ¿Cómo estás?",
    ["I'm not best pleased, Player. As far as my records say, absolutely no vizzy critters have been captured so far! It just don't make no sense. I guess I'll have to do it meself."] = "No estoy muy contento, Player. Por lo que dicen mis registros, ¡hasta ahora no se ha capturado absolutamente ningún bicho vizzy! Simplemente no tiene sentido. Supongo que tendré que hacerlo yo mismo.",
    ["I'm well happy, Player! I've been keeping count on how many of them vizzy critters have been caught. I reckon it must be about [number] already!"] = "¡Estoy muy feliz, Player! He estado contando cuántos de esos bichos vizzy han sido capturados. ¡Creo que ya debe ser sobre [número]!",
    ["Can you remind me about 'sumna critters', please?"] = "¿Puedes recordarme acerca de los 'bichos sumna', por favor?",
    ["Interesting question. You want the long or short answer?"] = "Pregunta interesante. ¿Quieres la respuesta larga o corta?",
    ["Short answer, definitely!"] = "Respuesta corta, ¡definitivamente!",
    ["**Yaktwee Swinmari Cianta:{{anchor|invizzy}}** Invizzy critters are invading our lands from the sumna realm and we could do with the help of a hunter like you. You'll need a sprite lure and a Yaktwee stick, which I can sell you."] = "**Yaktwee Swinmari Cianta:{{anchor|invizzy}}** Los bichos Invizzy están invadiendo nuestras tierras desde el reino sumna y nos vendría bien la ayuda de un cazador como tú. Necesitarás un señuelo para duendes y un palo Yaktwee, que puedo venderte.",
    ["Wield the stick, throw the sprite lure by targeting a moving bush - it'll automatically return to ya once you're done."] = "Empuña el palo, lanza el señuelo de duende apuntando a un arbusto en movimiento; volverá automáticamente a ti una vez que hayas terminado.",
    ["Okay, so I need a sprite lure and a Yaktwee stick, then I target a bush..."] = "Bien, entonces necesito un señuelo para sprites y un palo de Yaktwee, luego apunto a un arbusto...",
    ["Then explode the sprite lure by targeting it. This makes the critters vizzy. They'll try to escape, so target 'em quicky to transmute 'em into charm slices."] = "Luego explota el señuelo del sprite apuntándolo. Esto hace que los bichos se pongan nerviosos. Intentarán escapar, así que apúntalos rápidamente para transmutarlos en rodajas encantadoras.",
    ["Okay, so I target the sprite lure to make it explode, which should make the creatures visible. Then I have to target the creatures to transmute them into charm slices."] = "Bien, entonces apunto al señuelo del duende para hacerlo explotar, lo que debería hacer que las criaturas sean visibles. Luego tengo que apuntar a las criaturas para transmutarlas en rodajas de amuleto.",
    ["Exactly, that'll do it. They're all wrapped up into a handy charm slice, ready to fix into them sumna charms them crazy druid types in Taverley love so much."] = "Exacto, eso bastará. Están todos envueltos en una práctica porción de amuleto, lista para fijarlos en los amuletos sumna que tanto aman los druidas locos de Taverley.",
    ["Five slices to a charm and some of the slices, which we called mystical, can be used as a replacement for any slice."] = "Cinco porciones por amuleto y algunas de las porciones, que llamamos místicas, se pueden usar como reemplazo de cualquier porción.",
    ["Finally I can probably hold your stick and lure and some slices for you when you're done."] = "Finalmente probablemente pueda sostener tu palo, tu señuelo y algunas rodajas para ti cuando hayas terminado.",
    ["So you get Summoning charms from doing this?"] = "¿Entonces obtienes encantos Summoning al hacer esto?",
    ["Indeed you do!"] = "¡De hecho lo haces!",
    ["It's more like a slice of a charm from each critter, and you need five slices to make one charm."] = "Es más como una porción de un amuleto de cada bicho, y necesitas cinco porciones para hacer un amuleto.",
    ["They're no use ta me, so I just give 'em to Pikkupstix. You may find 'em useful, though! Yeah, you got a touch of that sumna energy in ya, I can tell!"] = "No me sirven, así que se los doy a Pikkupstix. ¡Sin embargo, puede que te resulten útiles! Sí, tienes un toque de esa energía sumna en ti, ¡lo noto!",
    ["What else do you get from doing this?"] = "¿Qué más obtienes al hacer esto?",
    ["Ya'll gain plenty of experience in the hunter ways! Like I say, I'm a jack-knife of all trades, but I was raised as a hunter and I'm a pretty experienced one at that."] = "¡Obtendrás mucha experiencia en el estilo de cazador! Como digo, soy un experto en todos los oficios, pero me criaron como cazador y tengo bastante experiencia en eso.",
    ["Most creatures in this world, and the next, quake in fear when I'm in the mood to hunt. Hunting these critters keeps me in superb shape, and has given me lots of new experiences."] = "La mayoría de las criaturas de este mundo y del próximo tiemblan de miedo cuando tengo ganas de cazar. Cazar estos bichos me mantiene en excelente forma y me ha brindado muchas experiencias nuevas.",
    ["Is this something I can do?"] = "¿Es esto algo que puedo hacer?",
    ["Hmm, well now, that's a thought! The critters still seem to be coming through, so you'd be helping to keep the numbers down."] = "Hmm, bueno, ¡eso es una idea! Los bichos todavía parecen estar apareciendo, por lo que ayudarías a mantener bajos los números.",
    ["Great, how do I do it?"] = "Genial, ¿cómo lo hago?",
    ["First you'll need a sprite lure - very valuable item that. You throw it near a bush when you think critters are nearby."] = "Primero necesitarás un señuelo para sprites, un elemento muy valioso. Lo arrojas cerca de un arbusto cuando crees que hay bichos cerca.",
    ["Okay, then what?"] = "Bien, ¿y luego qué?",
    ["Then you'll need a Yaktwee stick to fire some sumna-hunta energy at that sprite lure. That'll make them critters vizzy."] = "Entonces necesitarás un palo Yaktwee para disparar un poco de energía sumna-hunta a ese señuelo de duende. Eso hará que esos bichos se pongan nerviosos.",
    ["They'll be off like a shot, so quickly use your Yaktwee stick again to shoot 'em with more sumna-hunta energy before they get away."] = "Saldrán como un tiro, así que usa rápidamente tu bastón Yaktwee nuevamente para dispararles con más energía sumna-hunta antes de que se escapen.",
    ["Oh, yes, and they'll be off quicker than a fast thing once you make 'em vizzy! You won't have long and they're hard to hit!"] = "¡Oh, sí, y se apagarán más rápido que una cosa rápida una vez que los hagas vibrar! ¡No tendrás mucho tiempo y son difíciles de acertar!",
    ["Where can I get a sprite lure and Yaktwee stick?"] = "¿Dónde puedo conseguir un señuelo para sprites y un palo Yaktwee?",
    ["Well, I made spares, so I can let you have 'em for a small materials fee. Just ask me to open my store and I'll sort you out. And I'll tell you what. If you catch 1000 critters, I'll tweak your stick to improve the hunter experience you"] = "Bueno, hice repuestos, así que puedo dártelos por una pequeña tarifa de materiales. Sólo pídeme que abra mi tienda y te solucionaré. Y te diré una cosa. Si atrapas 1000 bichos, modificaré tu bastón para mejorar tu experiencia como cazador.",
    ["get while wielding it and it should also improve the sumna charm slices you get."] = "obtén mientras lo empuñas y también debería mejorar las porciones de amuleto sumna que obtienes.",
    ["Select an option{{anchor"] = "Seleccione una opción{{anchor",
    ["Can you open the shop please?"] = "¿Puedes abrir la tienda por favor?",
    ["Oooh, give me all the juicy details!"] = "¡Oooh, dame todos los detalles jugosos!",
    ["Okay then, steel yourself! One evening, Edina, a local gnome gatherer, was out picking neverberry leaves. She heard a horrendous cracking sound come from the dolmen here."] = "¡Está bien, entonces, prepárate! Una noche, Edina, una recolectora de local gnome, estaba recogiendo hojas de nunca jamás. Escuchó un crujido horrendo procedente del dolmen de aquí.",
    ["She was a little put out, but needed to finish collecting leaves for the family's aromatic brew. As she started picking, she felt a presence. Something moved around her that made her hairs stick on end."] = "Estaba un poco molesta, pero necesitaba terminar de recolectar hojas para la bebida aromática de la familia. Cuando empezó a picar, sintió una presencia. Algo se movió a su alrededor que le puso los pelos de punta.",
    ["Wracked with fear, she could barely move. Then, right in front of her, she saw the bush move as if some dark and evil force was at work."] = "Atormentada por el miedo, apenas podía moverse. Luego, justo frente a ella, vio que el arbusto se movía como si alguna fuerza oscura y maligna estuviera actuando.",
    ["A dark and evil force...made the bush move?"] = "Una fuerza oscura y maligna... ¿hizo que el arbusto se moviera?",
    ["As she watched on in horror,  of the leaves started to vanish."] = "Mientras observaba con horror, algunas de las hojas comenzaron a desaparecer.",
    ["So a dark evil force made some bush leaves vanish?"] = "¿Entonces una oscura fuerza maligna hizo desaparecer algunas hojas de arbusto?",
    ["Exactly! She fled for her life and reported the matter to the gnome authorities. An investigation took place immediately and the militia was put onto full alert."] = "¡Exactamente! Ella huyó para salvar su vida e informó del asunto a las autoridades gnomos. Inmediatamente se llevó a cabo una investigación y la milicia fue puesta en alerta máxima.",
    ["They patrolled the bushes but it didn't change a thing. More of the neverberry bushes started to shake. Spirit tree masters and local seers had no idea how to explain this strange mystery."] = "Patrullaron los arbustos pero eso no cambió nada. Más arbustos de moras comenzaron a temblar. Los maestros de Spirit tree y los videntes locales no tenían idea de cómo explicar este extraño misterio.",
    ["Eventually, the dolmen itself was investigated and there was a small breakthrough. I was in the area at the time and offered to lend a hand."] = "Finalmente, se investigó el dolmen y hubo un pequeño avance. Yo estaba en la zona en ese momento y me ofrecí a echar una mano.",
    ["Okay, so you have some experience in the field of dark and evil bush shaking creatures?"] = "Bien, ¿tienes algo de experiencia en el campo de las criaturas oscuras y malvadas que sacuden los arbustos?",
    ["Having some experience of the outside world, I knew a little about that sumna thing that druids know about. I had a suspicion that's what had affected the dolmen."] = "Al tener algo de experiencia en el mundo exterior, sabía un poco sobre esa cosa sumna que conocen los druidas. Tenía la sospecha de que eso era lo que había afectado al dolmen.",
    ["I've lived an itinerant lifestyle, see, so I know a little about the world. Anyway, I was sent as an envoy to see Pikkupstix in Taverley. He taught me all he could be bothered in two days and then sent me on my way."] = "He vivido un estilo de vida itinerante, así que sé un poco sobre el mundo. De todos modos, me enviaron como enviado para ver Pikkupstix en Taverley. Me enseñó todo lo que podía molestarle en dos días y luego me envió por mi camino.",
    ["So Pikkupstix knows something about dark and evil bush creatures?"] = "¿Entonces Pikkupstix sabe algo sobre las criaturas oscuras y malvadas del bosque?",
    ["I was unsure of the druidic ways I was being taught, but I knew I had to resolve the problem. I returned here and experimented a little with my newfound sumna knowledge."] = "No estaba seguro de las formas druidas que me enseñaban, pero sabía que tenía que resolver el problema. Regresé aquí y experimenté un poco con mi nuevo conocimiento de sumna.",
    ["I noticed that sumna shards vibrated when I was near a bush and when its leaves were shaking I reported this back to Pikkupstix and he got real interested."] = "Noté que los fragmentos de sumna vibraban cuando estaba cerca de un arbusto y cuando sus hojas temblaban, se lo informé a Pikkupstix y él se interesó mucho.",
    ["He showed me a little more about  energies and such like. Before too long, and with some druidic shenanigans, I was able to channel some of my hunter energies through my teasing stick into a sumna shard"] = "Me mostró un poco más sobre energías y cosas así. En poco tiempo, y con algunas travesuras druídicas, pude canalizar algunas de mis energías de cazador a través de mi palo provocador hacia un fragmento de sumna.",
    ["and..."] = "y...",
    ["BAM! I got to see the nature of the beast!"] = "¡BAM! ¡Pude ver la naturaleza de the beast!",
    ["*GASP!* What...what...what...?"] = "*¡GASP!* ¿Qué... qué... qué...?",
    ["I can guess what you're going to say: what did it look like? Well, let me tell you, it wasn't like anything you could ever imagine! Nothing can quite prepare you for the effect it has on you."] = "Puedo adivinar lo que vas a decir: ¿cómo era? Bueno, déjame decirte que ¡no se parecía a nada que puedas imaginar! Nada puede prepararte para el efecto que tiene en ti.",
    ["But my years of training and world experience put me in good stead. I was able to stare that twisted fiend right in the eye. This was the breakthrough that we had been waiting for."] = "Pero mis años de formación y experiencia mundial me resultaron muy útiles. Pude mirar a ese demonio retorcido directamente a los ojos. Este fue el gran avance que estábamos esperando.",
    ["Together we toiled, experimented and tested. We knew the critters were from the sumna realm, but they didn't respond to the normal sorts of related materials."] = "Juntos trabajamos, experimentamos y probamos. Sabíamos que las criaturas eran del reino sumna, pero no respondían a los tipos normales de materiales relacionados.",
    ["What happened then?"] = "¿Qué pasó entonces?",
    ["Well, with Pikkupstix in the region we worked night and day experimenting. We found that adding a sumna shard to a teasing stick helped with channeling energies."] = "Bueno, con Pikkupstix en la región trabajamos día y noche experimentando. Descubrimos que agregar un fragmento de sumna a un palo de burla ayudó a canalizar energías.",
    ["With this we could create a much larger burst of energy, which made the critters visible for much longer."] = "Con esto pudimos crear una explosión de energía mucho mayor, lo que hizo que las criaturas fueran visibles por mucho más tiempo.",
    ["We developed the tools and finally created the sprite lure and the Yaktwee stick."] = "Desarrollamos las herramientas y finalmente creamos el señuelo sprite y el palo Yaktwee.",
    ["I remember the first day we tested them. I threw my sprite lure at a bush that was moving as I knew there were critters around it, and then..."] = "Recuerdo el primer día que los probamos. Lancé mi señuelo de duende a un arbusto que se movía porque sabía que había bichos a su alrededor, y luego...",
    ["BAM! I fired my stick at the lure and it burst with energy. Them critters didn't know what hit 'em!"] = "¡BAM! Disparé mi palo al señuelo y estalló de energía. ¡Esos bichos no sabían qué los golpeó!",
    ["I saw 'em scarper for cover, rushing off all over the place, but then..."] = "Los vi correr en busca de refugio, corriendo por todos lados, pero entonces...",
    ["WHAM! I let loose another shot right at the critters."] = "¡ZAP! Solté otro tiro directo a los bichos.",
    ["Ya see, Pikkupstix and me found that the critters were actually the spirits inside of sumna charms. 'Charm sprites' he called them, but they're all just critters to me."] = "Ya ves, Pikkupstix y yo descubrimos que las criaturas eran en realidad los espíritus dentro de los amuletos sumna. Los llamó 'duendes encantadores', pero para mí todos son sólo bichos.",
    ["So what happened to the critters...erm, charm sprites?"] = "Entonces, ¿qué pasó con las criaturas... ejem, los duendes encantadores?",
    ["That's the really clever part! The sumna power from my stick grabs 'em and squashes 'em into a slice of a sumna charm. We could fix five of 'em slices together to make a whole charm! We even found some of 'em could be turned"] = "¡Esa es la parte realmente inteligente! El poder sumna de mi bastón los agarra y los aplasta en un trozo de amuleto sumna. ¡Podríamos juntar cinco rebanadas para hacer un amuleto completo! Incluso descubrimos que algunos de ellos podían convertirse",
    ["into any other charm. Mystical slices, we called 'em!"] = "en cualquier otro amuleto. ¡Rebanadas místicas, las llamábamos!",
    ["Very clever man, that Pikkupstix...and, er, myself of course!"] = "Un hombre muy inteligente, ese Pikkupstix... y, eh, ¡yo mismo, por supuesto!",
    ["Forget it!"] = "¡Olvídalo!",
    ["Could you store a few items for me?"] = "¿Podrías guardarme algunos artículos?",
    ["Sorry, friend, but I'm not storing things for those not skilled enough to use them."] = "Lo siento, amigo, pero no almacenaré cosas para aquellos que no tienen la habilidad suficiente para usarlas.",
    ["You need a Hunting skill of level 72 to catch charm sprites."] = "Necesitas una habilidad de caza de nivel 72 para atrapar duendes encantadores.",
    ["I ain't your familiar! But since you ask nicely, I'll be a sport and keep some of your things in my bag. Maybe you'll come back and catch more vizzy critters, then. If not, free stuff!"] = "¡No soy tu familiar! Pero como lo pides amablemente, seré muy amable y guardaré algunas de tus cosas en mi bolso. Entonces tal vez regreses y atrapes más bichos vizzy. Si no, ¡cosas gratis!",
    ["Sorry, friend, but I'll not be selling any of my stuff to those not skilled enough to use it."] = "Lo siento, amigo, pero no venderé ninguna de mis cosas a quienes no tengan la habilidad suficiente para usarlas.",
    ["Congratulations! You have completed: 'Yaktwee's a Charm' - Unlock the enhanced Yaktwee stick by catching charm sprites. (1,000/1,000)"] = "¡Felicitaciones! Has completado: 'Yaktwee's a Charm': desbloquea el palo Yaktwee mejorado capturando sprites de encanto. (1.000/1.000)",
    ["Hey, ye've just caught your 1,000th vizzy critter since I started counting. Come to see me and I'll upgrade your Yaktwee stick, free of charge!"] = "Oye, acabas de atrapar tu bicho vizzy número 1.000 desde que comencé a contar. ¡Ven a verme y actualizaré tu dispositivo Yaktwee, gratis!",
    ["Ah, Player. I see you've caught 1,000 vizzy critters recently, so I'll do you a favour and upgrade your Yaktwee stick. How about that?"] = "Ah, Player. Veo que has atrapado 1000 bichos vizzy recientemente, así que te haré un favor y mejoraré tu bastón Yaktwee. ¿Qué tal eso?",
    ["Sure!"] = "¡Claro!",
    ["There, I've improved your stick. Hope you're happy!"] = "Ahí, he mejorado tu bastón. ¡Espero que estés feliz!",
    ["Nah, I'll pass"] = "No, pasaré",
    ["Your loss!"] = "¡Tú te lo pierdes!",
    ["[You show Yaktwee the item.]"] = "[Le muestras a Yaktwee el artículo.]",
    ["Ah, you've got a better Yaktwee stick. A fine tool if ever I saw one, but then it would be...I made it! It's ain't much to look at, but it sure is tough, and it has special benefits as well! Extra hunter experience, better chances of mystical slices and looks fancier besides!"] = "Ah, tienes un bastón Yaktwee mejor. Una buena herramienta si alguna vez viera una, pero entonces sería... ¡La hice! No tiene mucho que ver, pero seguro que es resistente y ¡también tiene beneficios especiales! ¡Experiencia de cazador adicional, mejores posibilidades de cortes místicos y además luce más elegante!",
    ["Ah, you've made a fine purchase with that Yaktwee stick. A fine tool if ever I saw one, but then it would be...I made it! What it lacks in beauty, it more than makes up for in durability."] = "Ah, has hecho una buena compra con ese bastón Yaktwee. Una buena herramienta si alguna vez viera una, pero entonces sería... ¡La hice! Lo que le falta en belleza lo compensa con creces en durabilidad.",
    ["Hey, can you let me know what this is?"] = "Oye, ¿puedes decirme qué es esto?",
    ["Sure, it's a sprite lure. You need to throw that at one of the moving bushes, then target it with your Yaktwee stick. It'll make the critters vizzy!"] = "Claro, es un señuelo para duendes. Debes arrojarlo a uno de los arbustos en movimiento y luego apuntarlo con tu bastón Yaktwee. ¡Hará que los bichos se pongan nerviosos!",
    ["Hey, what's this?"] = "Oye, ¿qué es esto?",
    ["Ah, that's the bag for the sprite lure. You'll need that to store the sprite lure in your inventory. You'll notice that the lure returns to the bag before too long."] = "Ah, esa es la bolsa para el señuelo del duende. Lo necesitarás para almacenar el señuelo sprite en tu inventario. Notarás que el señuelo regresa a la bolsa en poco tiempo.",
    ["Aha! It looks like you've been catching them critters. Well done, friend. If you combine them, they'll turn into proper charms. I never have a use for 'em, but you might."] = "¡Ajá! Parece que has estado atrapando bichos. Bien hecho, amigo. Si los combinas, se convertirán en verdaderos amuletos. Nunca los uso, pero tú podrías hacerlo.",
    ["Aha! It looks like you've been catching them critters. Well done, friend. If you combine them, they'll turn into proper charms. That one's a mystical slice. Bit like a wildcard, that is. I never have a use for 'em, but you might."] = "¡Ajá! Parece que has estado atrapando bichos. Bien hecho, amigo. Si los combinas, se convertirán en verdaderos amuletos. Ésa es una porción mística. Un poco como un comodín, claro está. Nunca los uso, pero tú podrías hacerlo.",
    ["Sorry, friend, but I'm not sure why you're showing me that."] = "Lo siento, amigo, pero no estoy seguro de por qué me muestras eso.",
    ["Sorry, the shop isn't open yet. We're still getting it ready."] = "Lo sentimos, la tienda aún no está abierta. Todavía lo estamos preparando.",
    ["I'm getting out of here Bwana, the place is infested with zombies."] = "Me voy de aquí Bwana, el lugar está infestado de zombies.",
    ["Choose an option"] = "Elige una opción:",
    ["Tell me about this antiques business."] = "Háblame de este negocio de antigüedades.",
    ["I buy antiques and other interesting items. If you have any interesting items that you might want to sell me, please let me see them and I'll offer you a fair price. Would you like me to have a look at your items and give"] = "Compro antigüedades y otros artículos interesantes. Si tienes algún artículo interesante que quieras venderme, déjame verlo y te ofreceré un precio justo. ¿Quieres que eche un vistazo a tus artículos y te dé",
    ["you a quote?"] = "¿Tienes una cita?",
    ["Yes please!"] = "¡Sí, por favor!",
    ["Great Bwana!"] = "¡Qué bien Bwana!",
    ["I'll give you 100 Gold for the Bone Key."] = "Te daré 100 de oro por la llave de hueso.",
    ["I'll give you 100 Gold for the Stone-Plaque."] = "Te daré 100 de oro por la placa de piedra.",
    ["I'll give you 100 Gold for the tattered scroll."] = "Te daré 100 de oro por el pergamino hecho jirones.",
    ["I'll give you 100 Gold for the crumpled scroll."] = "Te daré 100 de oro por el pergamino arrugado.",
    ["I'll give you 500 Gold for your locating crystal."] = "Te daré 500 de oro por tu cristal de localización.",
    ["I'll give you 1000 Gold for your 'Beads of the Dead'."] = "Te daré 1000 de oro por tus 'Cuentas de los muertos'.",
    ["*(If the player has the black prism:)*"] = "*(Si el player tiene el prisma negro:)*",
    ["I'll give you 5000 Gold for your Black Prism."] = "Te daré 5000 de oro por tu Prisma Negro.",
    ["Those are the items I am interested in Bwana."] = "Esos son los artículos que me interesan en Bwana.",
    ["If you want to sell me those items, simply show them to me."] = "Si quieres venderme esos artículos, simplemente muéstramelos.",
    ["And that's the only item I am interested in."] = "Y ese es el único elemento que me interesa.",
    ["If you want to sell me that item, simply show it to me."] = "Si quieres venderme ese artículo, simplemente muéstramelo.",
    ["Sorry Bwana, you have nothing I am interested in."] = "Lo siento Bwana, no tienes nada que me interese.",
    ["Maybe some other time?"] = "¿Quizás en otro momento?",
    ["Sure thing. Have a nice day Bwana."] = "Claro. Que tengas un buen día Bwana.",
    ["Is there anything else interesting to do around here?"] = "¿Hay algo más interesante que hacer por aquí?",
    ["Hmm, sorry, not interested."] = "Hmm, lo siento, no estoy interesado.",
    ["Fair enough, come back if you change your mind."] = "Es justo, vuelve si cambias de opinión.",
    ["Do you have any interesting items for sale?"] = "¿Tiene algún artículo interesante a la venta?",
    ["I have a very fetching bead necklace and an unusual key!"] = "¡Tengo un collar de cuentas muy atractivo y una llave inusual!",
    ["Ask about the necklace."] = "Pregunta por el collar.",
    ["Yes [sir/madam], a very fetching bead necklace, apparently it aids adventurers in a plethora of different ways.{{anchor|beads}}"] = "Sí, [sir/madam], un collar de cuentas muy atractivo, aparentemente ayuda a los aventureros de muchas maneras diferentes.{{anchor|beads}}",
    ["[Yanni shows you the necklace. It seems somehow familiar to you.]"] = "[Yanni te muestra el collar. De alguna manera te parece familiar.]",
    ["An absolute bargain at 1200 gold coins!"] = "¡Una auténtica ganga a 1200 gold coins!",
    ["I'll take it!"] = "¡Lo aceptaré!",
    ["Very good [Sir/Madam]!"] = "¡Muy bien [Sir/Madam]!",
    ["[Yanni hands over the beads and takes the money from you.]"] = "[Yanni te entrega las cuentas y te quita el dinero.]",
    ["No thanks, not interested!"] = "¡No gracias, no estoy interesado!",
    ["No thanks, not interested"] = "No gracias, no estoy interesado",
    ["Very well [sir/madam], come back if you change your mind."] = "Muy bien [sir/madam], vuelve si cambias de opinión.",
    ["Ask about the key!"] = "¡Pregunta por la llave!",
    ["Yes [sir/madam], a very unusual key, apparently it allows access into a dangerous subterranean complex.{{anchor|bonekey}}"] = "Sí [sir/madam], una llave muy inusual, aparentemente permite acceder a un peligroso complejo subterráneo.{{anchor|bonekey}}",
    ["[Yanni shows you the key. It seems somehow familiar to you.]"] = "[Yanni te muestra la clave. De alguna manera te parece familiar.]",
    ["An absolute bargain at 100 gold coins!"] = "¡Una auténtica ganga a 100 gold coins!",
    ["[Yanni hands over the key and takes the money from you.]"] = "[Yanni te entrega la llave y te quita el dinero.]",
    ["That's a great bone key. here's 100 Gold for it."] = "Esa es una gran clave ósea. aquí tienes 100 de oro por ello.",
    ["You sell the bone key for 100 gold."] = "Vendes la llave de hueso por 100 de oro.",
    ["That's a great stone-plaque. here's 100 Gold for it."] = "Esa es una gran placa de piedra. aquí tienes 100 de oro por ello.",
    ["You sell the stone-plaque for 100 gold."] = "Vendes la placa de piedra por 100 de oro.",
    ["That's a great tattered scroll. here's 100 Gold for it."] = "Es un pergamino muy andrajoso. aquí tienes 100 de oro por ello.",
    ["You sell the tattered scroll for 100 gold."] = "Vendes el pergamino andrajoso por 100 de oro.",
    ["That's a great crumpled scroll. here's 100 Gold for it."] = "Es un pergamino arrugado fantástico. aquí tienes 100 de oro por ello.",
    ["You sell the crumpled scroll for 100 gold."] = "Vendes el pergamino arrugado por 100 de oro.",
    ["That's a great copy of Bervirius notes. here's 100 Gold for it."] = "Esa es una gran copia de las notas de Bervirius. aquí tienes 100 de oro por ello.",
    ["You sell the Bervirius notes for 100 gold."] = "Vendes los billetes de Bervirius por 100 de oro.",
    ["That's a great Locating Crystal. Here's 500 Gold for it."] = "Es un gran cristal de localización. Aquí tienes 500 de oro por ello.",
    ["You sell the locating crystal for 500 gold."] = "Vendes el cristal de localización por 500 de oro.",
    ["Impressive necklace there, here's 1000 Gold for it."] = "Impresionante collar, aquí tienes 1000 de oro por él.",
    ["You sell the 'Beads of the Dead' for 1000 gold."] = "Vendes las 'Cuentas de los Muertos' por 1000 de oro.",
    ["You show the black prism to Yanni."] = "Le muestras el prisma negro a Yanni.",
    ["Ah you'd like to sell this to me would you? I can offer you 5000 coins!"] = "Ah, ¿te gustaría venderme esto, verdad? ¡Puedo ofrecerte 5000 coins!",
    ["**SELL THE PRISM FOR 5000 COINS?**"] = "**¿VENDER EL PRISMA POR 5000 COINS?**",
    ["Yes, I'll sell it for 5000{{Sic}}"] = "Si, lo vendo por 5000{{Sic}}",
    ["Yes, I'll sell it for 5000 coins."] = "Sí, lo venderé por 5000 coins.",
    ["Very well my friend, let me count out your reward."] = "Muy bien amigo mío, déjame contar tu recompensa.",
    ["You sell the black prism for 5000 coins."] = "Vendes el prisma negro por 5000 coins.",
    ["Thanks!"] = "¡Gracias!",
    ["No, I think I'll hold on it a while longer yet."] = "No, creo que lo aguantaré un poco más todavía.",
    ["Very well my friend, come back if you change your mind."] = "Muy bien amigo, vuelve si cambias de opinión.",
    ["My secretary is sitting just over there, thank you."] = "Mi secretaria está sentada justo ahí, gracias.",
    ["Today is not a good day, can you come back tomorrow?"] = "Hoy no es un buen día, ¿puedes volver mañana?",
    ["I’m busy, please leave."] = "Estoy ocupado, por favor vete.",
    ["If you’re looking for the market, it’s downstairs."] = "Si buscas el mercado, está abajo.",
    ["I can't help you, go and see my secretary."] = "No puedo ayudarte, ve a ver a mi secretaria.",
    ["Talk to my secretary. I don’t have time to deal with you."] = "Habla con mi secretaria. No tengo tiempo para tratar contigo.",
    ["My secretary will deal with any inquiries you have about the Yellow Fortune."] = "Mi secretaria atenderá cualquier consulta que tengas sobre la Fortuna Amarilla.",
    ["Do you mind? You're blocking my view."] = "¿Te importa? Estás bloqueando mi vista.",
    ["But..."] = "Pero...",
    ["I said go!"] = "¡Dije que te fueras!",
    ["I told you to leave, human!"] = "¡Te dije que te fueras, humano!",
    ["You are an exceptional member of the Yellow Fortune."] = "Eres un miembro excepcional de Yellow Fortune.",
    ["Come in, Player, my secretary has been saying good things about you."] = "Pasa, Player, mi secretaria ha estado diciendo cosas buenas de ti.",
    ["Have you come to serve the Yellow Fortune again, Player?"] = "¿Has venido a servir a la Fortuna Amarilla otra vez, Player?",
    ["You are proving yourself a loyal member of the Yellow Fortune, Player!"] = "¡Estás demostrando que eres un miembro leal de Yellow Fortune, Player!",
    ["Player! I've been hearing great things about you!"] = "¡Player! ¡He estado escuchando cosas maravillosas sobre ti!",
    ["Come, Player, let us converse a while on your future with us."] = "Ven, Player, déjanos conversar un rato sobre tu futuro con nosotros.",
    ["What have you come to ask of us, honourable Player?"] = "¿Qué ha venido a pedirnos, honorable Player?",
    ["It's an honour to meet you!"] = "¡Es un honor conocerte!",
    ["Fine, fine, now what did you want to talk about?"] = "Bien, bien, ¿ahora de qué querías hablar?",
    ["And what was it that you wanted of me, Player?"] = "¿Y qué era lo que querías de mí, Player?",
    ["It certainly must be."] = "Ciertamente debe serlo.",
    ["Yes, well, don't overdo it now, will you?"] = "Sí, bueno, no te excedas ahora, ¿quieres?",
    ["You are one of our best people, Player, naturally I have time for you."] = "Eres una de nuestras mejores personas, Player, naturalmente tengo tiempo para ti.",
    ["I can imagine!"] = "¡Me lo imagino!",
    ["It's not everyday that you run into someone as important as me, I'm sure."] = "No todos los días te encuentras con alguien tan importante como yo, estoy seguro.",
    ["Do you have any more tasks for me?"] = "¿Tienes más tareas para mí?",
    ["**Player:{{anchor|www}}** Do you have any more tasks for me?"] = "**Player:{{anchor|www}}** ¿Tienes más tareas para mí?",
    ["Verily, I believe I do."] = "En verdad, creo que sí.",
    ["Why, certainly."] = "Pues, claro.",
    ["I do believe so, yes."] = "Eso creo, sí.",
    ["A moment please, let me check."] = "Un momento, por favor, déjame comprobarlo.",
    ["Yes, I have something appropriate for you here."] = "Sí, tengo algo apropiado para ti aquí.",
    ["**Yellow Fortune Director:{{anchor|eee}}** We need [number] bars of [metal] in the next [number] minutes."] = "**Yellow Fortune Director:{{anchor|eee}}** Necesitamos barras [número] de [metal] en los próximos minutos [número].",
    ["I'll take it."] = "Lo aceptaré.",
    ["Excellent, get to it now!"] = "Excelente, ¡hazlo ahora!",
    ["Happy to hear that!"] = "¡Feliz de escuchar eso!",
    ["Admirable attitude, Player!"] = "¡Actitud admirable, Player!",
    ["The Yellow Fortune appreciates what you're doing, Player."] = "La Fortuna Amarilla aprecia lo que estás haciendo, Player.",
    ["Then hurry back, Player, I'm counting on you!"] = "Entonces vuelve rápido, Player, ¡cuento contigo!",
    ["No thanks."] = "No, gracias.",
    ["I'm sorry to hear that, Player, the company really needed those bars."] = "Lamento escuchar eso, Player, la compañía realmente necesitaba esas barras.",
    ["I don't understand, I thought you were a loyal follower?"] = "No entiendo, ¿pensé que eras un seguidor leal?",
    ["Then why did you ask, Player?"] = "Entonces, ¿por qué preguntaste, Player?",
    ["That is an unusual thing to say for you, Player."] = "Eso es algo inusual para ti, Player.",
    ["Oh? I thought you liked doing this kind of work?"] = "¿Ah? Pensé que te gustaba hacer este tipo de trabajo.",
    ["Have you completed your current task yet? Did you get me my [number] bars of [metal]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis barras [número] de [metal]?",
    ["I'm still working on it, sorry."] = "Todavía estoy trabajando en ello, lo siento.",
    ["Hurry then, I don't have time for all this."] = "Entonces date prisa, no tengo tiempo para todo esto.",
    ["Since you're so fond of the [chosen company during The Giant Dwarf], why don't you ask them?"] = "Ya que te gustan tanto los [chosen company during The Giant Dwarf], ¿por qué no les preguntas?",
    ["You are in league with the [chosen company], aren't you? Your question is inappropriate."] = "Estás aliado con [chosen company], ¿no? Tu pregunta es inapropiada.",
    ["Ask the [chosen company] for a job instead!"] = "¡Pide trabajo al [chosen company]!",
    ["Aren't you an associate of [chosen company]? Why do you ask me?"] = "¿No eres asociado de [chosen company]? ¿Por qué me preguntas?",
    ["I believe that you have business with [other Company] to finish first."] = "Creo que tienes asuntos pendientes con [other Company] para terminar primero.",
    ["*(Only after The Giant Dwarf:)* The trade floor guards keep attacking me!"] = "*(Sólo después de The Giant Dwarf:)* ¡Los guardias del piso de comercio siguen atacándome!",
    ["The trade floor guards keep attacking me."] = "Los guardias del piso comercial siguen atacándome.",
    ["No doubt they thought you were stealing from the traders. You should speak to your own company director."] = "Sin duda pensaron que les estabas robando a los comerciantes. Debería hablar con el director de su propia empresa.",
    ["Thank you for your time."] = "Gracias por tu tiempo.",
    ["Don't mention it."] = "No lo menciones.",
    ["I've completed your task! Here are your bars!"] = "¡He completado tu tarea! ¡Aquí están tus barras!",
    ["The Yellow Fortune can always rely on you, Player."] = "La Fortuna Amarilla siempre puede confiar en ti, Player.",
    ["I will get my secretary to send this to the trade floor at once!"] = "¡Haré que mi secretaria envíe esto al parqué de inmediato!",
    ["Welcome back, Player, it's great to see you again!"] = "Bienvenido de nuevo, Player, ¡es un placer verte de nuevo!",
    ["And how can the Yellow Fortune be of service to you today, Player?"] = "¿Y cómo puede ayudarte la Fortuna Amarilla hoy, Player?",
    ["Come in, come in my friend!"] = "¡Entra, entra amigo mío!",
    ["The Yellow Fortune is pleased to see you again!"] = "¡La Fortuna Amarilla se complace en verte de nuevo!",
    ["Hello again, Player, come in!"] = "Hola de nuevo, Player, ¡pasa!",
    ["**Player:{{anchor|qwe}}** It's an honour to meet you!"] = "**Player:{{anchor|qwe}}** ¡Es un honor conocerte!",
    ["Delightful to see you again as well!"] = "¡Encantado de verte de nuevo también!",
    ["And I am honoured to make some time for you, Player!"] = "¡Y es un honor para mí dedicar algo de tiempo a ti, Player!",
    ["Don't mention it, Player!"] = "¡Ni lo menciones, Player!",
    ["Almost as much an honour as it is to meet you again, Player!"] = "¡Es casi tan honor como volver a encontrarte, Player!",
    ["I'm always happy to make time for you, Player!"] = "¡Siempre estoy feliz de tener tiempo para ti, Player!",
    ["It was time well spent!"] = "¡Fue un tiempo bien empleado!",
    ["Not at all, it was a delight to speak to you once more!"] = "Para nada, ¡fue un placer hablar contigo una vez más!",
    ["Guthix be praised!"] = "¡Alabado sea Guthix!",
    ["I am well pleased with your work, Player!"] = "¡Estoy muy satisfecho con tu trabajo, Player!",
    ["You are a true asset to the Yellow Fortune!"] = "¡Eres un verdadero activo para la Fortuna Amarilla!",
    ["You never fail to satisfy, Player!"] = "¡Nunca dejas de satisfacer, Player!",
    ["Hello Player! Have you seen the statue? It looks beautiful! The Yellow Fortune is indebted to you for your dedication in making this happen!"] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! ¡The Yellow Fortune está en deuda contigo por tu dedicación para hacer que esto suceda!",
    ["More work? My, you certainly are an asset to the company."] = "¿Más trabajo? Vaya, ciertamente eres un activo para la empresa.",
    ["Really, Player, you don't need to do this anymore."] = "De verdad, Player, ya no necesitas hacer esto.",
    ["But I want to!"] = "¡Pero quiero hacerlo!",
    ["Well, if you insist..."] = "Bueno, si insistes...",
    ["You don't need to do this anymore, you know?"] = "Ya no necesitas hacer esto, ¿sabes?",
    ["Ah, if only all the members of the Yellow Fortune had such dedication as you."] = "Ah, si tan solo todos los miembros de Yellow Fortune tuvieran tanta dedicación como tú.",
    ["The trade floor guards keep attacking me!"] = "¡Los guardias del piso de comercio siguen atacándome!",
    ["I might be able to get the guards off your back, if you perform a task for the company."] = "Quizás pueda quitarte los guardias de encima si realizas una tarea para la empresa.",
    ["Alright."] = "Muy bien.",
    ["Forget it."] = "Olvídalo.",
    ["Until later, then, my friend! I'm sure the Yellow Fortune will play a role in your future again at some point!"] = "¡Hasta luego, amigo! ¡Estoy seguro de que la Fortuna Amarilla volverá a desempeñar un papel en tu futuro en algún momento!",
    ["I'll have a word with the guards. They won't be watching you for the next ten minutes."] = "Hablaré con los guardias. No te estarán mirando durante los próximos diez minutos.",
    ["The trade floor guards are now bribed to ignore you."] = "Los guardias del piso de comercio ahora están sobornados para que lo ignoren.",
    ["Hello Player! Have you seen the statue? It looks beautiful! It's a pity it's been overshadowed by the departure of the Red Axe."] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! Es una pena que se haya visto eclipsado por la marcha del Red Axe.",
    ["Handing over power to the monarchy was the worst day of my life. At least King Veldaban has kept the Consortium around as an advisory body."] = "Entregar el poder a la monarquía fue el peor día de mi vida. Al menos el rey Veldaban ha mantenido al Consorcio como organismo asesor.",
    ["I hope you understand what you've done, human. You could have convinced Veldaban to step down and let the experts take over. Instead we're saddled with his ridiculous policies again."] = "Espero que entiendas lo que has hecho, humano. Podrías haber convencido a Veldaban de que renunciara y dejara que los expertos se hicieran cargo. En cambio, volvemos a cargar con sus ridículas políticas.",
    ["Things could be worse, I suppose. The new king is listening to the Consortium's advice... on the few occasions he's sober enough to understand it."] = "Las cosas podrían ser peores, supongo. El nuevo rey está escuchando los consejos del Consorcio... en las pocas ocasiones en que está lo suficientemente sobrio como para entenderlos.",
    ["Thanks for your support in the meeting, Player. Now Keldagrim can put the silly business of kings behind it and let the company directors manage things properly."] = "Gracias por tu apoyo en la reunión, Player. Ahora Keldagrim puede dejar atrás los tontos negocios de los reyes y dejar que los directores de la empresa gestionen las cosas correctamente.",
    ["I don't have much time for you, what do you want?"] = "No tengo mucho tiempo para ti, ¿qué quieres?",
    ["You're blocking my view, human, so hurry up."] = "Estás bloqueando mi vista, humano, así que date prisa.",
    ["Can we hurry this along?"] = "¿Podemos apurarnos?",
    ["Say what you want or get out of our office, human!"] = "¡Di lo que quieras o sal de nuestra oficina, humano!",
    ["Do not test the patience of the Yellow Fortune, human. Say what you need!"] = "No pongas a prueba la paciencia de la Fortuna Amarilla, humana. ¡Di lo que necesites!",
    ["I think I've misplaced my quill somewhere..."] = "Creo que perdí mi pluma en alguna parte...",
    ["Oh, and what did you want?"] = "Ah, ¿y qué querías?",
    ["I am the head secretary of the Yellow Fortune."] = "Soy el secretario principal de Yellow Fortune.",
    ["The what?"] = "¿El qué?",
    ["The Yellow Fortune! We are the grandest of the mining companies that make up the Consortium!"] = "¡La Fortuna Amarilla! ¡Somos la más grande de las empresas mineras que conforman el Consorcio!",
    ["How is that?"] = "¿Cómo es eso?",
    ["Why, because men are not allowed to work in our company, of course!"] = "¡Porque, porque a los hombres no se les permite trabajar en nuestra empresa, por supuesto!",
    ["Ha, I see what you mean!"] = "¡Ja, ya veo lo que quieres decir!",
    ["That’s a bit drastic, don’t you think?"] = "Eso es un poco drástico, ¿no crees?",
    ["We simply consider men to be weak and inferior."] = "Simplemente consideramos que los hombres son débiles e inferiores.",
    ["I think I better go now, I don’t like being insulted."] = "Creo que será mejor que me vaya ahora, no me gusta que me insulten.",
    ["Where am I?"] = "¿Dónde estoy?",
    ["I'm not here to give directions!"] = "¡No estoy aquí para dar instrucciones!",
    ["Do I look like a tour guide to you?"] = "¿Te parezco un guía turístico?",
    ["I'd tell you, human, but you wouldn't understand anyway."] = "Te lo diría, humano, pero de todos modos no lo entenderías.",
    ["These are the offices of the Yellow Fortune."] = "Estas son las oficinas de la Fortuna Amarilla.",
    ["We share this floor of the palace with the other companies of the Consortium. And trade with them on the Trade Octagon."] = "Compartimos esta planta del palacio con el resto de empresas del Consorcio. Y comercie con ellos en el octágono comercial.",
    ["The Trade Octagon?"] = "¿El octágono comercial?",
    ["See those traders standing out there, just out the door? They're all standing in the Trade Octagon. There's an awful lot of trade going on in the palace, you know."] = "¿Ves a esos comerciantes parados ahí afuera, justo afuera de la puerta? Todos están parados en el octágono comercial. Hay muchísimo comercio en el palacio, ¿sabes?",
    ["Anything else of interest in the palace?"] = "¿Algo más de interés en el palacio?",
    ["You will have to find that out on your own, I'm afraid. I do have more work to do."] = "Me temo que tendrás que descubrirlo por tu cuenta. Tengo más trabajo que hacer.",
    ["Is there anything I can help you with?"] = "¿Hay algo en lo que pueda ayudarte?",
    ["**Yellow Fortune Secretary:{{anchor|weak}}** The Yellow Fortune does not employ the services of men."] = "**Yellow Fortune Secretary:{{anchor|weak}}** La Fortuna Amarilla no emplea los servicios de hombres.",
    ["Why not?"] = "¿Por qué no?",
    ["We often find that they are too weak or too slow to be of sufficient use."] = "A menudo encontramos que son demasiado débiles o demasiado lentos para ser de suficiente utilidad.",
    ["You shouldn't say such things to people."] = "No deberías decirle esas cosas a la gente.",
    ["Come to redeem yourself at our company, have you?"] = "Ven a redimirte en nuestra empresa, ¿verdad?",
    ["So you're looking for work with us all of a sudden?"] = "¿Entonces de repente estás buscando trabajo con nosotros?",
    ["You're lucky the Yellow Fortune is very forgiving, human."] = "Tienes suerte de que la Fortuna Amarilla sea muy indulgente, humana.",
    ["I'm not sure if I'm allowed to give someone like you a task, I'll check."] = "No estoy seguro de poder asignarle una tarea a alguien como tú, lo comprobaré.",
    ["All right, you've been cleared."] = "Muy bien, has sido autorizado.",
    ["Your motives are questionable but we'll give you a chance."] = "Tus motivos son cuestionables, pero te daremos una oportunidad.",
    ["We need [number] pieces of [ore] in the next [number] minutes."] = "Necesitamos [número] piezas de [ore] en los próximos minutos [número].",
    ["Do no disappoint the Yellow Fortune, human."] = "No decepciones a la Fortuna Amarilla, humano.",
    ["Go then! The longer you stand here the more time you waste!"] = "¡Vete entonces! ¡Cuanto más tiempo estés aquí, más tiempo perderás!",
    ["Hurry back or don't come back at all!"] = "¡Date prisa o no vuelvas!",
    ["Let's hope I was wrong about you, human."] = "Esperemos haberme equivocado contigo, humano.",
    ["You'd better not fail!"] = "¡Será mejor que no falles!",
    ["Oh, so you were just stopping by to waste my time, then? Goodbye!"] = "Oh, ¿entonces viniste a hacerme perder el tiempo? ¡Adiós!",
    ["To say a thing like that after the mercy I just showed you! Go away!"] = "¡Decir algo así después de la misericordia que te acabo de mostrar! ¡Irse!",
    ["You dare!"] = "¡Te atreves!",
    ["Thought you wouldn't. Now get out of here!"] = "Pensé que no lo harías. ¡Ahora sal de aquí!",
    ["Leave now, don't make me call the Black Guard to throw you out!"] = "¡Vete ahora, no me hagas llamar al Black Guard para echarte!",
    ["Get out of our office then!"] = "¡Entonces sal de nuestra oficina!",
    ["The Yellow Fortune offers you a chance and you say this? Just stay away!"] = "La Fortuna Amarilla te ofrece una oportunidad ¿y dices esto? ¡Sólo mantente alejado!",
    ["Have you completed your current task yet? Did you get me my [number] pieces of [ore]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis piezas [número] de [ore]?",
    ["No, not yet."] = "No, todavía no.",
    ["You're a disgrace to the Yellow Fortune. Hurry up if you want to redeem yourself."] = "Eres una vergüenza para la Fortuna Amarilla. Date prisa si quieres redimirte.",
    ["Go back to your friends at the [other Company], I hear you're in league with them."] = "Vuelve con tus amigos del [other Company], he oído que estás aliado con ellos.",
    ["I have to go!"] = "¡Tengo que irme!",
    ["Finally...back to work at last."] = "Finalmente... por fin volvemos al trabajo.",
    ["Good."] = "Bien.",
    ["Don't hurry back."] = "No te apresures a regresar.",
    ["The door is over there. I suggest you use it."] = "La puerta está por ahí. Te sugiero que lo uses.",
    ["And good riddance to you."] = "Y adiós.",
    ["I've completed your task! Here is your ore!"] = "¡He completado tu tarea! ¡Aquí está tu mineral!",
    ["How unusual for you, but it is appreciated nonetheless."] = "Qué inusual para ti, pero de todos modos se agradece.",
    ["The Yellow Fortune is pleased that the trust it put in you has not been put to shame after all."] = "La Fortuna Amarilla se alegra de que, después de todo, la confianza que depositó en ti no haya sido avergonzada.",
    ["That is quite a pleasant and unexpected surprise."] = "Es una sorpresa bastante agradable e inesperada.",
    ["Perhaps I was wrong about you after all..."] = "Quizás me equivoqué contigo después de todo...",
    ["Thanks... I suppose."] = "Gracias... Supongo.",
    ["What did you need of the Yellow Fortune?"] = "¿Qué necesitabas de la Fortuna Amarilla?",
    ["And what can I do for you?"] = "¿Y qué puedo hacer por ti?",
    ["Is there anything you need assistance with?"] = "¿Hay algo con lo que necesites ayuda?",
    ["Can I help you with anything?"] = "¿Puedo ayudarte en algo?",
    ["Was there anything you wanted?"] = "¿Había algo que quisieras?",
    ["What can I do for you, human?"] = "¿Qué puedo hacer por ti, humano?",
    ["Why, this is the headquarters of the Yellow Fortune."] = "Vaya, esta es la sede de la Fortuna Amarilla.",
    ["There's always work to be done, yes."] = "Siempre hay trabajo por hacer, sí.",
    ["Just a moment."] = "Un momento.",
    ["Yes, the Yellow Fortune always has work to do!"] = "Sí, ¡la Fortuna Amarilla siempre tiene trabajo que hacer!",
    ["Let's see... yes, yes, I do have a task for you."] = "Veamos... sí, sí, tengo una tarea para ti.",
    ["Yes, I think we do have something for you."] = "Sí, creo que tenemos algo para ti.",
    ["I believe we have some work available, yes."] = "Creo que tenemos trabajo disponible, sí.",
    ["The Yellow Fortune has noted your willingness to help."] = "La Fortuna Amarilla ha notado tu disposición a ayudar.",
    ["That ore needs to go on the trade floor soon, player, please hurry back with it."] = "Ese mineral debe estar pronto en la sala de operaciones, jugador, por favor regresa con él.",
    ["Thanks, it's appreciated."] = "Gracias, se agradece.",
    ["The clock is ticking, please hurry back."] = "El tiempo corre, por favor regresa rápido.",
    ["I will await your return soon, then."] = "Entonces, esperaré tu regreso pronto.",
    ["Fair enough, maybe some other time?"] = "Muy bien, ¿tal vez en otro momento?",
    ["Please, it would be appreciated if you made up your mind before you ask. I'm very busy you know."] = "Por favor, le agradeceríamos que tomara una decisión antes de preguntar. Estoy muy ocupado, ¿sabes?",
    ["Please, in that case, you're wasting my time."] = "Por favor, en ese caso, estás perdiendo el tiempo.",
    ["That's unfortunate to hear."] = "Es lamentable escuchar eso.",
    ["I can't say I'm too pleased to hear that, to be honest."] = "Para ser honesto, no puedo decir que esté muy contento de escuchar eso.",
    ["That does not reflect well on you."] = "Eso no te refleja bien.",
    ["The Yellow Fortune isn't too pleased to hear that."] = "La Fortuna Amarilla no está muy contenta de escuchar eso.",
    ["Then please, hurry up before time runs out."] = "Entonces, por favor, apúrate antes de que se acabe el tiempo.",
    ["From what I understand, you have some business to finish with the [other Company] first."] = "Por lo que tengo entendido, primero tienes algunos asuntos que terminar con el [other Company].",
    ["See you later."] = "Hasta luego.",
    ["Okay."] = "Está bien.",
    ["Goodbye, human."] = "Adiós, humano.",
    ["I have to admit, I was worried for a moment, but I'm glad to see you came through for us."] = "Tengo que admitir que estuve preocupado por un momento, pero me alegra ver que nos ayudaste.",
    ["I am happy to see that the trust we put in you has not been in vain."] = "Me alegra comprobar que la confianza que depositamos en vosotros no ha sido en vano.",
    ["And not a minute too late as well. Well done."] = "Y ni un minuto tarde también. Bien hecho.",
    ["The Yellow Fortune recognizes your performance."] = "La Fortuna Amarilla reconoce tu desempeño.",
    ["That's good to hear, thanks."] = "Es bueno escucharlo, gracias.",
    ["How may the Yellow Fortune assist you today?"] = "¿Cómo puede ayudarte la Fortuna Amarilla hoy?",
    ["And what can I do for you on this fine day?"] = "¿Y qué puedo hacer por ti en este lindo día?",
    ["Come to help us some more, Player?"] = "¿Ven a ayudarnos un poco más, Player?",
    ["Oh, hello there Player! Nice to see you!"] = "¡Oh, hola Player! ¡Qué bueno verte!",
    ["Welcome back to the palace of Keldagrim, Player!"] = "¡Bienvenido de nuevo al palacio de Keldagrim, Player!",
    ["Come in, come in! And tell us what you need!"] = "¡Entra, entra! ¡Y cuéntanos qué necesitas!",
    ["Where am I? {{anchor|high2}}"] = "¿Dónde estoy? {{anchor|high2}}",
    ["The top floor of the palace is the Meeting Octagon. That's the place where the Consortium makes all the important decisions."] = "El último piso del palacio es el Octágono de Reuniones. Ese es el lugar donde el Consorcio toma todas las decisiones importantes.",
    ["Can I go there?"] = "¿Puedo ir allí?",
    ["Oh, yes, you certainly can. But not while the Consortium is in session, I would imagine."] = "Oh, sí, ciertamente puedes. Pero me imagino que no mientras el Consorcio esté en sesión.",
    ["Even though you are a very friendly human, I'm not sure if you would be allowed to visit during a meeting."] = "Aunque eres una persona muy amigable, no estoy seguro de si se te permitiría visitarnos durante una reunión.",
    ["But I don't know enough about that, the director probably knows more."] = "Pero no sé lo suficiente sobre eso, el director probablemente sepa más.",
    ["Thanks for the info!"] = "¡Gracias por la información!",
    ["Ah, always looking for ways to help us!"] = "¡Ah, siempre buscando formas de ayudarnos!",
    ["Naturally, my good human, naturally!"] = "¡Por supuesto, mi buen humano, por supuesto!",
    ["Of course, we reserve our best tasks just for you, Player!"] = "¡Por supuesto, reservamos nuestras mejores tareas solo para ti, Player!",
    ["I do believe we do, yes!"] = "Creo que sí, ¡sí!",
    ["I dare say we have something for you, yes."] = "Me atrevo a decir que tenemos algo para ti, sí.",
    ["Oh yes, as you know the Yellow Fortune always has work!"] = "¡Oh, sí, como sabes, la Fortuna Amarilla siempre tiene trabajo!",
    ["You never disappoint, Player!"] = "¡Nunca decepcionas, Player!",
    ["Excellent, I thought you'd like this!"] = "¡Excelente, pensé que te gustaría esto!",
    ["I'm happy to hear that!"] = "¡Me alegra escuchar eso!",
    ["The Yellow Fortune appreciates the hard work you do."] = "Yellow Fortune aprecia el arduo trabajo que haces.",
    ["Thanks! But hurry back please, we really need that ore!"] = "¡Gracias! Pero date prisa, por favor, ¡realmente necesitamos ese mineral!",
    ["I suppose you have other important business to attend to?"] = "Supongo que tienes otros asuntos importantes que atender.",
    ["Oh. Didn't know you were the type to refuse work."] = "Ah. No sabía que eras del tipo que rechaza el trabajo.",
    ["Is everything okay? I didn't think you normally refused our tasks."] = "¿Está todo bien? No pensé que normalmente rechazaras nuestras tareas.",
    ["That's a great shame, Player."] = "Es una gran lástima, Player.",
    ["No? That's unusual for you, Player."] = "¿No? Eso es inusual para ti, Player.",
    ["Sorry to hear that, but please hurry up!"] = "Lamento escuchar eso, ¡pero apúrate!",
    ["Don't you have some business with [other company] to deal with first? Hurry back when you're done!"] = "¿No tienes algún asunto con [other company] que tratar primero? ¡Date prisa cuando hayas terminado!",
    ["It was a pleasure to talk to you again, Player."] = "Fue un placer volver a hablar contigo, Player.",
    ["Come back any time!"] = "¡Vuelve cuando quieras!",
    ["See you soon!"] = "¡Hasta pronto!",
    ["Wonderful! I will personally oversee that it goes to the trade floor on time!"] = "¡Maravilloso! ¡Supervisaré personalmente que llegue a tiempo al parqué!",
    ["Well done, well done!"] = "¡Bien hecho, bien hecho!",
    ["I knew you were the right human for the job!"] = "¡Sabía que eras la persona adecuada para el trabajo!",
    ["Thanks, I will make sure the director hears of your expeditiousness!"] = "¡Gracias, me aseguraré de que el director se entere de su rapidez!",
    ["You're always reliable, Player!"] = "¡Siempre eres confiable, Player!",
    ["I'm afraid I have no more work to offer you, Player, please speak to the director."] = "Me temo que no tengo más trabajo que ofrecerte, Player, por favor habla con el director.",
    ["You should speak directly to the director."] = "Deberías hablar directamente con el director.",
    ["*If the player doesn't have Yelps's very own cash bag in their inventory or bank:*"] = "*Si el player no tiene la propia bolsa de efectivo de Yelps en su inventario o banco:*",
    ["*If the player hasn't yet opened the cash bag:*"] = "*Si el player aún no ha abierto la bolsa de efectivo:*",
    ["*If the player has already opened the cash bag:*"] = "*Si el player ya abrió la bolsa de efectivo:*",
    ["You find an empty cashbag."] = "Encuentra una bolsa de dinero vacía.",
    ["*If the player doesn't have Expired spin ticket in their inventory or bank:*"] = "*Si el player no tiene un boleto de giro vencido en su inventario o banco:*",
    ["You find an expired spin ticket."] = "Encuentra un boleto de giro vencido.",
    ["*If the player has both items in their inventory or bank already:*"] = "*Si el player ya tiene ambos artículos en su inventario o banco:*",
    ["You find nothing."] = "No encuentras nada.",
    ["Helloooo! I'm Yelps!"] = "¡Hola! ¡Soy Yelps!",
    ["I'm Yelps, the richest and smartest goblin that ever lived!"] = "¡Soy Yelps, el duende más rico e inteligente que jamás haya existido!",
    ["It comes in handy, because I'm also the smallest goblin that ever lived."] = "Es útil porque también soy el duende más pequeño que jamás haya existido.",
    ["I'm an entrepreneur! A self-made man!"] = "¡Soy emprendedor! ¡Un hombre hecho a sí mismo!",
    ["Really? What do you do?"] = "¿En serio? ¿A qué te dedicas?",
    ["I used to run this game, see? Lucky people would punch me in the face to win prizes!"] = "Solía ejecutar este juego, ¿ves? ¡La gente afortunada me daría un puñetazo en the face para ganar premios!",
    ["They...punched you in the face to win prizes?"] = "¿Ellos... te golpearon en the face para ganar premios?",
    ["That's right!"] = "¡Así es!",
    ["But how... Never mind."] = "Pero cómo... No importa.",
    ["What do you do?"] = "¿A qué te dedicas?",
    ["Well, the game I used to run all sort of fell through."] = "Bueno, el juego que solía ejecutar fracasó.",
    ["It turned out the treasure I was givin' away actually belonged to some human princess or something, so I had to give most of it up."] = "Resultó que el tesoro que estaba regalando en realidad pertenecía a alguna princesa humana o algo así, así que tuve que renunciar a la mayor parte.",
    ["She's still runnin' the game but..."] = "Ella todavía está dirigiendo el juego pero...",
    ["*shudder*"] = "*estremecimiento*",
    ["There's no punchin'. Not even a bit!"] = "No hay golpes. ¡Ni siquiera un poquito!",
    ["There are... treasure chests!"] = "¡Hay... cofres del tesoro!",
    ["I've been trying to reintegrate into goblin society, but it's not going so well."] = "He estado intentando reintegrarme a la sociedad de los duendes, pero no va muy bien.",
    ["Why are you here?"] = "¿Por qué estás aquí?",
    ["The high priest told me to get my best gear on and guard the camp! Here I am!"] = "¡El sumo sacerdote me dijo que me pusiera mi mejor equipo y vigilara el campamento! ¡Aquí estoy!",
    ["*Before finding all the human infiltrators*"] = "*Antes de encontrar a todos los infiltrados humanos*",
    ["You're not taking part?"] = "¿No vas a participar?",
    ["Not on yer life! I'm no warrior!"] = "¡No en tu vida! ¡No soy un guerrero!",
    ["*After finding all the human infiltrators*"] = "*Después de encontrar a todos los infiltrados humanos*",
    ["You do realise you're the goblin champion, don't you? You're fighting me in the first round."] = "Te das cuenta de que eres el campeón goblin, ¿no? Vas a pelear conmigo en el primer round.",
    ["Y-you what? That can't be right."] = "¿T-tú qué? Eso no puede estar bien.",
    ["I'm done here."] = "Ya terminé aquí.",
    ["Hey, if it isn't my favourite human! How ya doing?"] = "¡Oye, si no es mi humano favorito! ¿Cómo estás?",
    ["I'm good. What are you doing in the goblin village?"] = "Estoy bien. ¿Qué estás haciendo en la aldea de los duendes?",
    ["I got a job as Wartface and Bentnoze's manservant."] = "Conseguí un trabajo como sirviente de Wartface y Bentnoze.",
    ["Since Grubfoot left for Dorgesh-Kaan they've been doing their own cooking and cleaning and it has not worked out well, let me tell you."] = "Desde que Grubfoot se fue a Dorgesh-Kaan han estado cocinando y limpiando ellos mismos y no ha funcionado bien, déjame decirte.",
    ["It's good honest work, but to be honest I miss the pomp and the razzmatazz of the game show scene!"] = "Es un buen trabajo honesto, pero, para ser honesto, extraño la pompa y el alboroto de la escena de los programas de juegos.",
    ["I heard there are a couple of fellows who do some sort of show in some sort of pit. I thought I might apply there."] = "Escuché que hay un par de tipos que hacen algún tipo de espectáculo en una especie de foso. Pensé que podría postularme allí.",
    ["Ooh nice littlefoot costume!"] = "¡Qué bonito disfraz de piecito!",
    ["Wait... what? No, I'm a human."] = "Espera... ¿qué? No, soy un humano.",
    ["Of course you are..."] = "Por supuesto que sí...",
    ["Tell me about yourself."] = "Háblame de ti.",
    ["Me? I'm an adventurer! I travel the lands looking for people to help, monsters to slay and doing any favours anyone has."] = "¿Yo? ¡Soy un aventurero! Viajo por las tierras buscando gente que me ayude, monstruos que matar y haciendo cualquier favor que alguien tenga.",
    ["Oh really? Well, if you don't mind I've got a request if you wouldn't mind helping. It shouldn't be much for an adventurer like you. After all, it's only... ONE SMALL FAVOUR!"] = "¿En serio? Bueno, si no te importa, tengo una petición si no te importaría ayudar. No debería ser mucho para un aventurero como tú. Después de todo, es sólo... ¡UN PEQUEÑO FAVOR!",
    ["Why won't you believe me?"] = "¿Por qué no me crees?",
    ["Look at your movements. They're so realistic, but I can spot a fake anywhere. Good try though!"] = "Mira tus movimientos. Son muy realistas, pero puedo detectar una falsificación en cualquier lugar. ¡Buen intento!",
    ["I'm leaving."] = "Me voy.",
    ["See you around, littlefoot."] = "Nos vemos, piecito.",
    ["Want to trade?"] = "¿Quieres comerciar?",
    ["Salty Goods."] = "Productos salados.",
    ["Farewell."] = "Adiós.",
    ["Greetings!"] = "¡Saludos!",
    ["I am Yinteng and I am in charge of the Zodiac Festival!"] = "¡Soy Yinteng y estoy a cargo del Festival Zodiac!",
    ["*(Only after asking something else, and if not asked last:)*"] = "*(Solo después de preguntar algo más, y si no se preguntó al final:)*",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
    ["What do I have to do?"] = "¿Qué tengo que hacer?",
    ["Okay, so here's the deal, I need Zodiac Talismans."] = "Bien, este es el trato: necesito Talismanes del Zodíaco.",
    ["They are literally everywhere so you're bound to find them while you're out and about doing your usual activities."] = "Están literalmente en todas partes, por lo que seguramente los encontrarás mientras estás fuera y realizando tus actividades habituales.",
    ["But if you want a little extra there are plenty of tasks which need to be done."] = "Pero si quieres un poco más, hay muchas tareas que debes realizar.",
    ["A new task will appear in the Events Panel every day and will last 3 days before disappearing."] = "Cada día aparecerá una nueva tarea en el Panel de Eventos y durará 3 días antes de desaparecer.",
    ["Whenever you gather enough Zodiac Talismans you will be able to trade them in for some fantastic rewards!"] = "¡Siempre que recolectes suficientes Talismanes del Zodiaco podrás intercambiarlos por fantásticas recompensas!",
    ["What rewards are there?"] = "¿Qué recompensas hay?",
    ["Oh, you're in for a treat!"] = "¡Oh, te espera un placer!",
    ["Not only do we have the glorious Zodiac Shield, we also have this adorable little lion pet."] = "No solo tenemos el glorioso Escudo del Zodíaco, también tenemos esta adorable mascota león.",
    ["Just look at him! Who's a good boy? You're a good boy, yes you are! You're a good boy!"] = "¡Míralo! ¿Quién es un buen chico? Eres un buen chico, ¡sí lo eres! ¡Eres un buen chico!",
    ["Uh, Yinteng?"] = "Eh, ¿Yinteng?",
    ["Huh? Oh, sorry, what were we talking about again?"] = "¿Eh? Oh, lo siento, ¿de qué estábamos hablando otra vez?",
    ["Goodbye."] = "Adiós.",
    ["Take care!"] = "¡Cuídate!",
    ["*(If there are zodiac talismans to hand in:)*"] = "*(Si hay talismanes del zodíaco para entregar:)*",
    ["*(Dialogue from handing in zodiac talismans occurs, then continues below.)*"] = "*(Se produce el diálogo sobre la entrega de los talismanes del zodíaco y luego continúa a continuación.)*",
    ["What can I do for you today?"] = "¿Qué puedo hacer por ti hoy?",
    ["*(As on first time.)*"] = "*(Como la primera vez.)*",
    ["The Zodiac Festival was a great success. I hope you enjoyed it!"] = "El Festival Zodiac fue un gran éxito. ¡Espero que lo hayas disfrutado!",
    ["You do not have anything to hand in."] = "No tienes nada que entregar.",
    ["Handing in event currency will increase your progress for this event unlocking unique rewards. This will remove all currency from your bags and pouch.<br><br>Do you wish to continue?"] = "Entregar la moneda del evento aumentará tu progreso en este evento y desbloqueará recompensas únicas. Esto eliminará todo el dinero de sus bolsos y carteras.<br><br>¿Desea continuar?",
    ["Yes"] = "si",
    ["Congratulations, you have levelled up to level 2."] = "Felicitaciones, has subido de nivel al nivel 2.",
    ["Congratulations, you have unlocked the Zodiac Shield Override."] = "Felicitaciones, has desbloqueado la Anulación del Escudo del Zodíaco.",
    ["Congratulations, you have levelled up to level 3."] = "Felicitaciones, has subido de nivel al nivel 3.",
    ["Congratulations, you received Event mystery box x1."] = "Felicitaciones, recibió 1 caja misteriosa del evento.",
    ["Congratulations, you have levelled up to level 4."] = "Felicitaciones, has subido de nivel al nivel 4.",
    ["Congratulations, you received Big event mystery box x1."] = "Felicitaciones, recibió 1 caja misteriosa de gran evento.",
    ["Congratulations, you have levelled up to level 5."] = "Felicitaciones, has subido de nivel al nivel 5.",
    ["Congratulations, you have unlocked the Tea Service Resting Override."] = "Felicitaciones, ha desbloqueado la anulación del descanso del servicio de té.",
    ["Congratulations, you have levelled up to level 6."] = "Felicitaciones, has subido de nivel al nivel 6.",
    ["Congratulations, you have levelled up to level 7."] = "Felicitaciones, has subido de nivel al nivel 7.",
    ["Congratulations, you have levelled up to level 8."] = "Felicitaciones, has subido de nivel al nivel 8.",
    ["Congratulations, you have levelled up to level 9."] = "Felicitaciones, has subido de nivel al nivel 9.",
    ["Congratulations, you have levelled up to level 10."] = "Felicitaciones, has subido de nivel hasta el nivel 10.",
    ["Congratulations, you have unlocked the Foo pet Override."] = "Felicitaciones, has desbloqueado la Anulación de mascota Foo.",
    ["I'm getting out of here Bwana, the place is infested with Zombies."] = "Me voy de aquí Bwana, el lugar está infestado de zombis.",
    ["Hello."] = "Hola.",
    ["Hello. Feel free to use the blacksmith's furnace."] = "Hola. Siéntete libre de utilizar el horno de herrero.",
    ["Sorry but the blacksmiths is closed. But I can let you use the furnace at the cost of 20 gold pieces."] = "Lo siento, pero la herrería está cerrada. Pero puedo dejarte usar el horno por 20 piezas de oro.",
    ["Thanks Bwana! Enjoy the facilities!"] = "¡Gracias Bwana! ¡Disfruta de las instalaciones!",
    ["No thanks!"] = "¡No, gracias!",
    ["Very well Bwana, have a nice day."] = "Muy bien Bwana, que tengas un buen día.",
    ["No, there is too much at stake here, you will not interfere. {{Audio button|Yor'Ger the Deceiver - No, there is too much at stake.ogg}}"] = "No, hay mucho en juego aquí, no interferirás. {{Audio button|Yor'Ger the Deceiver - No, there is too much at stake.ogg}}",
    ["We have planned too long, worked too hard. {{Audio button|Yor'Ger the Deceiver - We have planned too long.ogg}}"] = "Hemos planeado demasiado, hemos trabajado demasiado. {{Audio button|Yor'Ger the Deceiver - We have planned too long.ogg}}",
    ["Our time shall come. We shall reclaim what was ours! {{Audio button|Yor'Ger the Deceiver - Our time will come.ogg}}"] = "Nuestro momento llegará. ¡Reclamaremos lo que era nuestro! {{Audio button|Yor'Ger the Deceiver - Our time will come.ogg}}",
    ["Ga ga?"] = "¿Ga ga?",
    ["Heeheehee!"] = "¡Jejejeje!",
    ["*cough*"] = "*tos*",
    ["*gurgle*"] = "*gorgoteo*",
    ["*hic*"] = "*hip*",
    ["Hello!"] = "¡Hola!",
    ["I'm sorry outerlander, I cannot sell you any clothes. Our customs forbid it."] = "Lo siento, outsider, no puedo venderte ropa. Nuestras costumbres lo prohíben.",
    ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Only Fremenniks may buy clothes here."] = "Sólo los Fremenniks pueden comprar ropa aquí.",
    ["I'm sorry outerlander, I cannot assist you. Our customs forbid it."] = "Lo siento, outsider, no puedo ayudarte. Nuestras costumbres lo prohíben.",
    ["Welcome to my clothes shop. I can change your shoes, or I've got a fine selection of clothes for sale."] = "Bienvenido a mi tienda de ropa. Puedo cambiarte los zapatos o tengo una excelente selección de ropa a la venta.",
    ["I'd like to buy some clothes."] = "Me gustaría comprar algo de ropa.",
    ["I'd like to change my shoes."] = "Me gustaría cambiarme de zapatos.",
    ["*(If the player is wielding a weapon:)*"] = "*(Si el player está empuñando un arma:)*",
    ["I don't feel comfortable helping you try on shoes when you are wielding something. Please remove what you are holding first."] = "No me siento cómodo ayudándote a probarte zapatos cuando estás empuñando algo. Primero retire lo que tiene en sus manos.",
    ["*(If the player is not wielding a weapon but is wearing something on the feet slot or has a feet override active:)*"] = "*(Si el player no empuña un arma pero lleva algo en la ranura de los pies o tiene una anulación de pies activa:)*",
    ["You'll have to take what you're wearing on your feet off first."] = "Primero tendrás que quitarte lo que llevas puesto.",
    ["You will need to remove anything worn on your feet and also disable any feet overrides before you can change your shoes."] = "Deberá quitarse todo lo que lleve puesto en los pies y también desactivar las anulaciones de los pies antes de poder cambiarse los zapatos.",
    ["*(If the player is not wielding anything and isn't wearing anything on the feet slot and doesn't have a feet override active:)*"] = "*(Si el player no empuña nada y no lleva nada en la ranura para los pies y no tiene una anulación de pies activa:)*",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["As you wish."] = "Como desees.",
    ["I've completed all of the Medium Tasks in the Fremennik set."] = "He completado todas las tareas medianas del conjunto Fremennik.",
    ["So you have. I have some special boots I've kept aside for you."] = "Así es. Tengo unas botas especiales que he guardado para ti.",
    ["Although, you'll have to come back when you've the space to take them."] = "Aunque tendrás que regresar cuando tengas espacio para tomarlos.",
    ["There you go. They're powerful things in their own way, so take care to study them and find all the ways they can help you."] = "Ahí lo tienes. Son cosas poderosas a su manera, así que tenga cuidado de estudiarlas y encontrar todas las formas en que pueden ayudarle.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Fremennik Province set, you are presented with a pair of sea boots."] = "Por completar el conjunto Fremennik Province, se te presenta un par de botas de mar.",
    ["These boots will become increasingly useful with each difficulty level of the set that you complete."] = "Estas botas serán cada vez más útiles con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the tasks in a set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas en un conjunto de una dificultad particular, luego podrás reclamar tu recompensa.",
    ["Some of the Fremennik set's Tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Fremennik son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["Ta claim yer Fremennik set rewards, speak to the council workman on the bridge south of Rellekka, Advisor Ghrim on Miscellania, or myself."] = "Para reclamar las recompensas del conjunto Fremennik, habla con council workman en el puente al sur de Rellekka, Advisor Ghrim en Miscellania o conmigo mismo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Fremennik sea boots 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "Fremennik sea boots 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
    ["[You're handed another Fremennik sea boots 1.]"] = "[Te entregan otro Fremennik sea boots 1.]",
    ["Fremennik sea boots 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "Fremennik sea boots 2? Sí, pero me temo que te costaría 2500 coins.",
    ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
    ["[You're handed another Fremennik sea boots 2.]"] = "[Te entregan otro Fremennik sea boots 2.]",
    ["Fremennik sea boots 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "Fremennik sea boots 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
    ["[You're handed another Fremennik sea boots 3.]"] = "[Te entregan otro Fremennik sea boots 3.]",
    ["Fremennik sea boots 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "Fremennik sea boots 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
    ["[You're handed another Fremennik sea boots 4.]"] = "[Te entregan otro Fremennik sea boots 4.]",
    ["Thanks for all your help!"] = "¡Gracias por toda tu ayuda!",
    ["Thank you for helping me reach your realm adventurer. We have work to do!"] = "Gracias por ayudarme a llegar a tu reino aventurero. ¡Tenemos trabajo que hacer!",
    ["Hey ya."] = "Hola, sí.",
    ["Can I help you?"] = "¿Puedo ayudarte?",
    ["Not really I just wanted to chat."] = "En realidad no, sólo quería charlar.",
    ["Sorry, I do not have time for idle gossip. Good day."] = "Lo siento, no tengo tiempo para chismes. Buen día.",
    ["Greetings, stranger. Have you been sent to help us in the fight to purify this area from the invading corruption?"] = "Saludos, extraño. ¿Ha sido enviado para ayudarnos en la lucha para purificar esta zona de la corrupción invasora?",
    ["I am so glad. We need everyone we can get."] = "Me alegro mucho. Necesitamos a todos los que podamos conseguir.",
    ["I can only hope that you still want to help when I have given you more details."] = "Sólo puedo esperar que todavía quieras ayudar cuando te haya dado más detalles.",
    ["That is a shame. There is grave danger here."] = "Eso es una pena. Aquí hay un grave peligro.",
    ["Maybe if you hear my tale you will be willing to help?"] = "¿Tal vez si escuchas mi historia estarás dispuesto a ayudar?",
    ["Would you like a charmed sack so you can collect corruption?"] = "¿Te gustaría un saco encantado para poder recolectar corrupción?",
    ["You do not have enough space to carry the sack at the moment."] = "No tienes suficiente espacio para llevar el saco en este momento.",
    ["There you go."] = "Ahí lo tienes.",
    ["Is there any other help that I can give you?"] = "¿Hay alguna otra ayuda que pueda brindarte?",
    ["Hello again, Player."] = "Hola de nuevo, Player.",
    ["How can I help?"] = "¿Cómo puedo ayudar?",
    ["Faith is the answer."] = "La fe es la respuesta.",
    ["The creature is a being of malice and evil; a scar on our land. In this way, it holds the seeds of its own destruction."] = "La criatura es un ser de malicia y maldad; una cicatriz en nuestra tierra. De esta manera, contiene las semillas de su propia destrucción.",
    ["The reason it polluted the area is that it cannot survive in pure conditions."] = "La razón por la que contaminó el área es que no puede sobrevivir en condiciones puras.",
    ["So we purify the land?"] = "¿Entonces purificamos la tierra?",
    ["Even better. With our faith and strength of spirit channelled into the pillars, we can purify the corruption that it is spewing forth and feed it back to itself, purifying it from the inside out."] = "Aún mejor. Con nuestra fe y fuerza de espíritu canalizadas en los pilares, podemos purificar la corrupción que está arrojando y retroalimentarla a sí misma, purificándola de adentro hacia afuera.",
    ["In this way we will destroy the beast and remove its foul grip on the land."] = "De esta manera destruiremos the beast y eliminaremos su asqueroso control sobre la tierra.",
    ["How does it work?"] = "¿Cómo funciona?",
    ["The Nexus where that thing is trying to break through is the key. Its corruption, the power it uses to taint the land, escapes."] = "El Nexo por donde esa cosa intenta abrirse paso es la clave. Su corrupción, el poder que utiliza para contaminar la tierra, escapa.",
    ["If we collect this corruption, the foul orange cloud, we can feed it back to it through the pillars."] = "Si recolectamos esta corrupción, la repugnante nube naranja, podemos devolverla a través de los pilares.",
    ["In order to use the pillars you need to use the power of prayer."] = "Para usar los pilares necesitas usar el poder de la oración.",
    ["How does prayer help?"] = "¿Cómo ayuda la oración?",
    ["How do I collect the corruption?"] = "¿Cómo recojo la corrupción?",
    ["Is there a way to speed up the process?"] = "¿Hay alguna manera de acelerar el proceso?",
    ["Let's get down to business."] = "Pongámonos manos a la obra.",
    ["How does faith help?"] = "¿Cómo ayuda la fe?",
    ["This is simpler than it sounds."] = "Esto es más simple de lo que parece.",
    ["Each bowl on the pillars is attuned to a different aspect of the spirit: order, chaos, battle and fealty - for which everyone has the potential."] = "Cada cuenco sobre los pilares está en sintonía con un aspecto diferente del espíritu: orden, caos, batalla y lealtad, para lo cual todos tienen el potencial.",
    ["All you have to do is muster your strength of will, holding the necessary aspect firmly in your heart as you pour the corruption into the bowl, and the pillars will do the rest."] = "Todo lo que tienes que hacer es reunir tu fuerza de voluntad, manteniendo firmemente el aspecto necesario en tu corazón mientras viertes la corrupción en el cuenco, y los pilares harán el resto.",
    ["Your spiritual strength will increase as you do this."] = "Tu fuerza espiritual aumentará a medida que hagas esto.",
    ["The charmed sack that you have has been woven to allow it to hold the corruption."] = "El saco encantado que tienes ha sido tejido para permitirle contener la corrupción.",
    ["Go to the Nexus to collect the corruption."] = "Ve al Nexus para recoger la corrupción.",
    ["We have found that the effect of the purification is much stronger if each of the pillars is channelling a different aspect."] = "Hemos descubierto que el efecto de la purificación es mucho más fuerte si cada uno de los pilares canaliza un aspecto diferente.",
    ["This seems to amplify the purity that we are sending into the Nexus, and I can feel the evil there recoiling."] = "Esto parece amplificar la pureza que estamos enviando al Nexo, y puedo sentir el mal retroceder allí.",
    ["There is, however, a side effect to this."] = "Sin embargo, esto tiene un efecto secundario.",
    ["What are the side effects?"] = "¿Cuáles son los efectos secundarios?",
    ["When it gets angered it uses this energy to try to break through the Nexus."] = "Cuando se enoja, utiliza esta energía para intentar atravesar el Nexo.",
    ["It rarely gets far - usually just interrupting the flow for a few moments - but sometimes..."] = "Rara vez llega lejos, generalmente solo interrumpe el flujo por unos momentos, pero a veces...",
    ["Go on..."] = "Continúa...",
    ["It...emerges, showing its unspeakable face. You must be ready to banish it with every ounce of your will if this happens."] = "Él... emerge, mostrando su rostro indescriptible. Debes estar preparado para desterrarlo con cada gramo de tu voluntad si esto sucede.",
    ["It cannot be allowed to break free!"] = "¡No se puede permitir que se libere!",
    ["What is happening here?"] = "¿Qué está pasando aquí?",
    ["Our beautiful land has been contaminated by that horror. It must be stopped."] = "Nuestra hermosa tierra ha sido contaminada por ese horror. Hay que detenerlo.",
    ["What is that thing?"] = "¿Qué es esa cosa?",
    ["It is a creature of nightmares. I do not know its name, and do not wish to. It is an abomination and must be stopped."] = "Es una criatura de pesadillas. No sé su nombre y no deseo saberlo. Es una abominación y hay que detenerlo.",
    ["What kind of creature is it?"] = "¿Qué clase de criatura es?",
    ["Again, I do not know. many years, warping the land into the dank morass you see here. That is why I call it the Grotesque."] = "Nuevamente, no lo sé. muchos años, transformando la tierra en el pantano húmedo que ves aquí. Por eso lo llamo Grotesco.",
    ["If it has been here for many years, why was there no evidence of it?"] = "Si ha estado aquí durante muchos años, ¿por qué no había pruebas de ello?",
    ["Oh, there was. Have you ever been to the tunnels beneath these swamps and seen the hands reaching from the walls? They were the first evidence of this horror."] = "Oh, lo hubo. ¿Alguna vez has estado en los túneles debajo de estos pantanos y has visto las manos saliendo de las paredes? Fueron la primera evidencia de este horror.",
    ["Why didn't you do something back then?"] = "¿Por qué no hiciste algo en aquel entonces?",
    ["Ah, if we had known then what we do now, perhaps we could have salvaged some of this area; stopped the growth of the monstrosity."] = "Ah, si hubiéramos sabido entonces lo que hacemos ahora, tal vez podríamos haber salvado parte de esta área; Detuvo el crecimiento de la monstruosidad.",
    ["My mentor - Augrum - came to study the area when he heard about the hands. For all his wisdom, he had no way of knowing the extent of the evil here."] = "Mi mentor, Augrum, vino a estudiar el área cuando se enteró de las manos. A pesar de toda su sabiduría, no tenía forma de saber el alcance del mal aquí.",
    ["What did he do?"] = "¿Qué hizo?",
    ["For some time he studied the hands and the surrounding area, but without knowing how insidious the creature was. He thought it was safe - that it wasn't growing...that it wouldn't hurt us."] = "Durante algún tiempo estudió las manos y el área circundante, pero sin saber cuán insidiosa era la criatura. Pensó que era seguro, que no estaba creciendo... que no nos haría daño.",
    ["So he sent me - his apprentice - to watch over the area."] = "Así que me envió a mí, su aprendiz, a vigilar la zona.",
    ["By the time I realised the extent of the danger, it was too late."] = "Cuando me di cuenta de la magnitud del peligro, ya era demasiado tarde.",
    ["When it became clear it was growing in power, I called Augrum to investigate."] = "Cuando quedó claro que su poder estaba creciendo, llamé a Augrum para investigar.",
    ["It was clear to Augrum that the corruption in the area had grown and that - left unchecked - it could destroy the area."] = "Augrum tenía claro que la corrupción en la zona había aumentado y que, si no se controlaba, podría destruir la zona.",
    ["So he went away, to seek help fighting the beast."] = "Entonces se fue a buscar ayuda para luchar contra the beast.",
    ["Where did he go?"] = "¿A dónde fue?",
    ["He went to visit some druids he'd heard of, far from here. He never said where exactly - only that they had some...radical ideas."] = "Fue a visitar a unos druidas de los que había oído hablar, lejos de aquí. Nunca dijo dónde exactamente, sólo que tenían algunas... ideas radicales.",
    ["Those were the hardest times, being here with that evil growing, not knowing when - or if - Augrum was going to come back."] = "Esos fueron los momentos más difíciles, estar aquí con ese mal creciendo, sin saber cuándo, o si, Augrum iba a regresar.",
    ["But he did?"] = "¿Pero lo hizo?",
    ["Yes. After many months he came back. This was only a few days ago. He came with some of the druids he'd spoken of - wild-eyed, feral men in tattered robes - carrying the four pillars you see here between them."] = "Sí. Después de muchos meses regresó. Esto fue hace sólo unos días. Vino con algunos de los druidas de los que había hablado (hombres salvajes con ojos desorbitados y túnicas hechas jirones) llevando los cuatro pilares que ves aquí entre ellos.",
    ["Augrum was very ill when he got back - he was an old man, and the journey had taken its toll. Also, the price he paid for the druids' assistance was...high."] = "Augrum estaba muy enfermo cuando regresó; era un old man y el viaje le había pasado factura. Además, el precio que pagó por la ayuda de los druidas fue... alto.",
    ["What cost?"] = "¿Cuánto cuesta?",
    ["I cannot bring myself to speak of that now. Suffice it to say that he died in the cause of protecting the land. Perhaps later we will speak further on this."] = "No puedo atreverme a hablar de eso ahora. Baste decir que murió por la causa de proteger la tierra. Quizás más adelante hablemos más sobre esto.",
    ["What did the druids do?"] = "¿Qué hicieron los druidas?",
    ["The druids did not speak, not even to Augrum. They just set up the pillar in the formation you see, and dug the channels. When they had finished, they simply left."] = "Los druidas no hablaron, ni siquiera con Augrum. Simplemente colocaron el pilar en la formación que ves y cavaron los canales. Cuando terminaron, simplemente se fueron.",
    ["I spent most of that time with Augrum, as he explained to me how the pillars can be used to force back the evil."] = "Pasé la mayor parte de ese tiempo con Augrum, mientras él me explicaba cómo se pueden usar los pilares para hacer retroceder al mal.",
    ["I am Ysondria: Guardian of the Nexus. It is my responsibility to make sure that the monstrosity trying to break through doesn't get out to spread its evil elsewhere."] = "Soy Ysondria: Guardián del Nexo. Es mi responsabilidad asegurarme de que la monstruosidad que intenta abrirse paso no salga y propague su maldad en otros lugares.",
    ["What is the Nexus?"] = "¿Qué es el Nexus?",
    ["It is the point at which the creature is trying to break through the surface, but also where it is at its weakest; its most exposed."] = "Es el punto en el que la criatura intenta atravesar la superficie, pero también donde está más débil; está más expuesto.",
    ["Not right now."] = "No ahora mismo.",
    ["I wish you luck and hope that you will work hard to aid this."] = "Te deseo suerte y espero que trabajes duro para ayudar en esto.",
    ["You already have a charmed sack. Collect corruption from the Nexus and purify it at one of the pillars."] = "Ya tienes un saco encantado. Recoge la corrupción del Nexus y purifícala en uno de los pilares.",
    ["Thank you again, Player. I was worried this day would not come, but you have stopped the corruption."] = "Gracias de nuevo, Player. Me preocupaba que este día no llegara, pero ustedes han detenido la corrupción.",
    ["There is some residual energy in the sack. Allow me to release it back to you."] = "Hay algo de energía residual en el saco. Permítame devolvérselo.",
    ["I shall be forever grateful for your aid in releasing this land."] = "Estaré eternamente agradecido por su ayuda para liberar esta tierra.",
    ["The effects of the purification can already be seen. I believe that the memory of Augrum is honoured by the work completed here."] = "Los efectos de la purificación ya se pueden ver. Creo que the memory de Augrum se siente honrado por el trabajo realizado aquí.",
    ["Select an Option {{anchor"] = "Seleccione una opción {{anchor",
    ["How can I train my spiritual skills now?"] = "¿Cómo puedo entrenar mis habilidades espirituales ahora?",
    ["Traditionally, ceremonial burial is used to honour the dead. To do this, you need to bury the bones of those that have been killed."] = "Tradicionalmente, el entierro ceremonial se utiliza para honrar a los muertos. Para hacer esto, debes enterrar los huesos de los que han sido asesinados.",
    ["As I understand it, the more powerful that the creature was when it was alive, the greater the experience you receive from burying the bones."] = "Según tengo entendido, cuanto más poderosa era la criatura cuando estaba viva, mayor es la experiencia que recibes al enterrar los huesos.",
    ["If you are devoted to training your spiritual abilities, you can create a gilded altar in your home to boost this process."] = "Si te dedicas a entrenar tus habilidades espirituales, puedes crear un altar dorado en tu casa para impulsar este proceso.",
    ["I have also heard of something called the Ectofuntus, which grants increased experience from bones, but I do not know what this is. All I do know is that it is located near to Port Phasmatys, far to the north-east."] = "También he oído hablar de algo llamado Ectofuntus, que otorga mayor experiencia a partir de huesos, pero no sé qué es. Lo único que sé es que está situado cerca de Port Phasmatys, muy al noreste.",
    ["Who is Augrum?"] = "¿Quién es Augrum?",
    ["Augrum was my mentor. He gave his life creating those relics as a means to release the land from its inevitable decay."] = "Augrum fue mi mentor. Dio su vida creando esas reliquias como un medio para liberar a la tierra de su inevitable decadencia.",
    ["He was a very brave and kind-hearted man, and I am grateful for your help in realising his intent."] = "Era un hombre muy valiente y de buen corazón, y agradezco su ayuda para hacer realidad su intención.",
    ["Will the area stay cleansed?"] = "¿El área permanecerá limpia?",
    ["I believe that it will, through the hard work that you have done here. I will not allow that evil to come back."] = "Creo que así será, gracias al arduo trabajo que has realizado aquí. No permitiré que ese mal vuelva.",
    ["Why are you still here?"] = "¿Por qué sigues aquí?",
    ["I feel close to Augrum here, and I want to ensure that everyone knows what he did, and what he sacrificed in order to free this land from that corruption."] = "Me siento cercano a Augrum aquí y quiero asegurarme de que todos sepan lo que hizo y lo que sacrificó para liberar esta tierra de esa corrupción.",
    ["I also wish to spread the word about all of the people who joined the fight and stood against the horror, using their faith and inner strength to save the land."] = "También deseo hacer correr la voz sobre todas las personas que se unieron a la lucha y se enfrentaron al horror, usando su fe y fuerza interior para salvar la tierra.",
    ["Your aid will always be remembered."] = "Tu ayuda siempre será recordada.",
    ["The effects of the purification can already be seen. believe that the memory of Augrum is honoured by the work completed here."] = "Los efectos de la purificación ya se pueden ver. Creo que the memory de Augrum se siente honrado por el trabajo realizado aquí.",
    ["I shall be forever grateful for your aid in releasing this land. Your work is done here."] = "Estaré eternamente agradecido por su ayuda para liberar esta tierra. Tu trabajo está hecho aquí.",
    ["I knew you'd come. Here, take this."] = "Sabía que vendrías. Toma, toma esto.",
    ["[Ysondria has given you a challenge scroll!]"] = "[¡Ysondria te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
    ["That's not right at all."] = "Eso no está nada bien.",
    ["[Ysondria has given you another clue scroll!]"] = "[¡Ysondria te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Correct!"] = "¡Correcto!",
    ["Looking for something? Or someone?"] = "¿Buscas algo? ¿O alguien?",
    ["Yeah, I'm trying to track down a man called Jed. He's also known as the Iron Link."] = "Sí, estoy intentando localizar a un hombre llamado Jed. También se le conoce como Enlace de Hierro.",
    ["Can't say I've heard of such a person, and I make it my business to know everyone."] = "No puedo decir que haya oído hablar de una persona así, y me propongo conocer a todos.",
    ["Well, I guess it was a long shot. I figured he'd be quite notorious in the Arc."] = "Bueno, supongo que era una posibilidad remota. Pensé que sería bastante famoso en el Arco.",
    ["You don't have a sapling planted in that patch. Plant one and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Plante uno y tal vez acepte cuidarlo por usted.",
    ["Alright, but it's not going to be cheap! I want [3/5] monkey nuts, a monkey bar and a ground-up Suqah tooth."] = "Muy bien, ¡pero no será barato! Quiero nueces de mono [3/5], una barra y un diente de Suqah molido.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["You don't have a sapling planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Planta algo y tal vez acepte cuidarlo por ti.",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["First, I want [3/5] monkey nuts, a monkey bar and a ground up suqah tooth."] = "Primero, quiero nueces de mono [3/5], una barra de mono y un diente de suqah molido.",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["Where can I get all that stuff?"] = "¿Dónde puedo conseguir todo eso?",
    ["You can get a Suqah tooth from a Suqah's mouth, of course. Then you grind it up with a pestle and mortar. As for the monkey bar and nuts, try looking somewhere where there are lots of monkeys!"] = "Puedes obtener un diente de Suqah de la boca de una Suqah, por supuesto. Luego lo mueles con un mortero. En cuanto a la barra de monos y las nueces, ¡intenta buscar en algún lugar donde haya muchos monos!",
    ["Alright, I'll pay."] = "Muy bien, pagaré.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["What the heck do you want with THAT?"] = "¿Qué diablos quieres con ESO?",
    ["They're for eating, silly! What else<br>can you do with a monkey bar?"] = "¡Son para comer, tonto! ¿Qué más<br>puedes hacer con una barra de mono?",
    ["And the Suqah tooth?"] = "¿Y el diente de Suqah?",
    ["Lots of gnomes like a bit of ground-up Suqah tooth, just don't tell anyone about this, okay?"] = "A muchos gnomos les gusta un poco de diente de Suqah molido, pero no le cuentes a nadie sobre esto, ¿de acuerdo?",
    ["Forget I asked."] = "Olvida que pregunté.",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
}

